#[derive(Clone, Debug)]
struct ReceiveOnlyTransport {
    local_node_id: NodeId,
    incoming: VecDeque<DfsRoutedMessage>,
}

impl ReceiveOnlyTransport {
    fn new(local_node_id: NodeId) -> Self {
        Self {
            local_node_id,
            incoming: VecDeque::new(),
        }
    }

    fn push_message(
        &mut self,
        source_node_id: NodeId,
        target_node_id: NodeId,
        message: DfsNetworkMessage,
    ) {
        self.incoming.push_back(build_dfs_routed_message(
            &source_node_id,
            &target_node_id,
            1,
            1,
            message,
        ));
    }
}

impl DfsTransportIdentity for ReceiveOnlyTransport {
    fn local_node_id(&self) -> &NodeId {
        &self.local_node_id
    }
}

impl DfsMessageTransport for ReceiveOnlyTransport {
    fn send_routed_call(
        &mut self,
        target_node_id: &NodeId,
        _call: DfsRoutedCall,
    ) -> Result<(), NetworkError> {
        Err(NetworkError::UnknownNode {
            node_id: target_node_id.clone(),
        })
    }

    fn drain_incoming_messages(&mut self) -> Result<Vec<DfsRoutedMessage>, NetworkError> {
        Ok(self.incoming.drain(..).collect())
    }
}

#[test]
fn detached_message_worker_finishes_every_lane_local_parent_touch() {
    let root = temp_root("detached-worker-drains-parent-touches");
    let node = NodeId::from_legacy_named("node_detached_parent_touches").expect("node id");
    let sender: DfsMessageSender = Arc::new(|target_node_id, command, _timeout| {
        Err(DfsPeerTransportError::new(format!(
            "unexpected send to {target_node_id} for {}",
            command.request_id
        )))
    });
    let transport = DfsNodeServedMessageTransport::new_with_message_sender(
        node,
        Vec::new(),
        sender,
        Duration::from_millis(1),
    );
    let content = LocalContentStore::new(root.join("content")).expect("content store");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut service = NetworkedDfsService::new(transport, content)
        .with_metadata_backend(metadata)
        .expect("attach metadata backend");
    service
        .bootstrap_distributed_sifs()
        .expect("bootstrap distributed SIFS");
    let mut parent_versions = Vec::new();
    for index in 0..(DFS_DEFERRED_PARENT_TOUCH_DRAIN_LIMIT + 3) {
        let parent = format!("/services/deferred-parent-{index}");
        service.posix_mkdir_all(&parent).expect("create parent");
        service
            .posix_set_times(&parent, Some(12_345), Some(67_890))
            .expect("set old parent times");
        let before = service.posix_stat(&parent).expect("parent before touch");
        let child = format!("{parent}/created.txt");
        service.deferred_routed_create_parent_touches.insert(child);
        parent_versions.push((parent, before.version));
    }

    let worker = service.detach_message_deferred_work();

    assert!(service.deferred_routed_create_parent_touches.is_empty());
    assert!(!worker.has_pending().expect("detached outbox state"));
    for (parent, version_before) in parent_versions {
        let after = service.posix_stat(&parent).expect("parent after touch");
        assert_ne!(
            after.version, version_before,
            "detaching must apply the queued metadata touch for {parent}"
        );
        assert!(
            after.modified_at_unix_nanos > 67_890,
            "detaching must refresh the queued parent mtime for {parent}"
        );
    }
}

#[derive(Debug)]
struct RangeSignalingControlPlaneKvClient {
    inner: InProcessKvStore,
    first_metadata_shard_range: std::sync::mpsc::SyncSender<()>,
    armed: AtomicBool,
    metadata_shard_range_count: AtomicUsize,
}

impl RangeSignalingControlPlaneKvClient {
    fn new(first_metadata_shard_range: std::sync::mpsc::SyncSender<()>) -> Self {
        Self {
            inner: InProcessKvStore::new(),
            first_metadata_shard_range,
            armed: AtomicBool::new(false),
            metadata_shard_range_count: AtomicUsize::new(0),
        }
    }

    fn arm(&self) {
        self.metadata_shard_range_count.store(0, Ordering::SeqCst);
        self.armed.store(true, Ordering::SeqCst);
    }

    fn metadata_shard_range_count(&self) -> usize {
        self.metadata_shard_range_count.load(Ordering::SeqCst)
    }
}

impl Clone for RangeSignalingControlPlaneKvClient {
    fn clone(&self) -> Self {
        Self {
            inner: self.inner.clone(),
            first_metadata_shard_range: self.first_metadata_shard_range.clone(),
            armed: AtomicBool::new(self.armed.load(Ordering::SeqCst)),
            metadata_shard_range_count: AtomicUsize::new(
                self.metadata_shard_range_count.load(Ordering::SeqCst),
            ),
        }
    }
}

impl DfsControlPlaneKvClient for RangeSignalingControlPlaneKvClient {
    fn refresh_latest(&mut self) -> Result<(), KvError> {
        DfsControlPlaneKvClient::refresh_latest(&mut self.inner)
    }

    fn get(&self, key: &str) -> Result<Option<KvEntry>, KvError> {
        DfsControlPlaneKvClient::get(&self.inner, key)
    }

    fn range_prefix(&self, prefix: &str) -> Result<Vec<KvEntry>, KvError> {
        let entries = DfsControlPlaneKvClient::range_prefix(&self.inner, prefix)?;
        if prefix.contains("/metadata-shards/") {
            self.metadata_shard_range_count
                .fetch_add(1, Ordering::SeqCst);
            if self.armed.swap(false, Ordering::SeqCst) {
                let _ = self.first_metadata_shard_range.send(());
            }
        }
        Ok(entries)
    }

    fn put(&mut self, key: String, value: Vec<u8>) -> Result<KvRevision, KvError> {
        DfsControlPlaneKvClient::put(&mut self.inner, key, value)
    }

    fn txn(&mut self, txn: KvTxn) -> Result<KvTxnResponse, KvError> {
        DfsControlPlaneKvClient::txn(&mut self.inner, txn)
    }
}

#[test]
fn namespace_set_owner_preserves_legacy_wire_shape() {
    #[derive(Debug, serde::Serialize, serde::Deserialize, Eq, PartialEq)]
    #[serde(rename_all = "kebab-case")]
    enum LegacyNamespaceOwnerOperation {
        SetOwner { path: String, uid: u32, gid: u32 },
    }

    let legacy = LegacyNamespaceOwnerOperation::SetOwner {
        path: "/users/legacy-owner".to_string(),
        uid: 1001,
        gid: 1002,
    };
    let current = DfsNamespaceOperation::SetOwner {
        path: "/users/legacy-owner".to_string(),
        uid: 1001,
        gid: 1002,
    };
    let codec = sinomo_core::network::SinomoObjectCodec::network_frame();
    let legacy_bytes = codec.encode(&legacy).expect("encode legacy SetOwner");
    let current_bytes = codec.encode(&current).expect("encode current SetOwner");
    assert_eq!(
        current_bytes, legacy_bytes,
        "SetOwner must retain its original path/uid/gid wire shape"
    );
    assert_eq!(
        codec
            .decode::<LegacyNamespaceOwnerOperation>(&current_bytes)
            .expect("decode current SetOwner as legacy"),
        legacy
    );
    assert_eq!(
        codec
            .decode::<DfsNamespaceOperation>(&legacy_bytes)
            .expect("decode legacy SetOwner as current"),
        current
    );

    for operation in [
        DfsNamespaceOperation::SetSymlinkOwner {
            path: "/users/link-owner".to_string(),
            uid: 1001,
            gid: 1002,
        },
        DfsNamespaceOperation::MkdirWithAttrs {
            path: "/users/private".to_string(),
            attrs: DfsPosixCreateAttrs::new(0o700, 1001, 1002),
        },
    ] {
        let bytes = codec.encode(&operation).expect("encode new operation");
        assert_ne!(bytes, legacy_bytes);
        assert!(
            codec
                .decode::<LegacyNamespaceOwnerOperation>(&bytes)
                .is_err(),
            "new operation must not masquerade as legacy SetOwner"
        );
    }
}

#[test]
fn exclusive_create_message_fails_closed_for_legacy_peers() {
    #[allow(dead_code)]
    #[derive(Debug, serde::Deserialize)]
    #[serde(rename_all = "kebab-case")]
    enum LegacyDfsNetworkMessage {
        DistributedWriteRequest(DfsDistributedWriteCommand),
    }

    let requester = NodeId::from_legacy_named("node_exclusive_create_wire").expect("node");
    let object_id =
        DfsObjectId::from_legacy_named("object_exclusive_create_wire").expect("object id");
    let mut command = test_routed_write_command("exclusive_create_wire", &requester, &object_id);
    command.exclusive_create = true;

    let codec = sinomo_core::network::SinomoObjectCodec::network_frame();
    let bytes = codec
        .encode(&DfsNetworkMessage::ExclusiveCreateRequest(command.clone()))
        .expect("encode exclusive create message");
    assert!(
        codec.decode::<LegacyDfsNetworkMessage>(&bytes).is_err(),
        "a peer that only understands overwrite-capable distributed writes must reject exclusive create"
    );
    assert_eq!(
        codec
            .decode::<DfsNetworkMessage>(&bytes)
            .expect("decode exclusive create message"),
        DfsNetworkMessage::ExclusiveCreateRequest(command)
    );
}

#[test]
fn dfs_request_ids_remain_unique_across_service_restarts() {
    let node = NodeId::from_legacy_named("node_request_id_restart").expect("node");
    let first_root = temp_root("request-id-first");
    let restarted_root = temp_root("request-id-restarted");
    let mut first = NetworkedDfsService::new(
        ReceiveOnlyTransport::new(node.clone()),
        LocalContentStore::new(&first_root).expect("first content"),
    );
    let mut restarted = NetworkedDfsService::new(
        ReceiveOnlyTransport::new(node),
        LocalContentStore::new(&restarted_root).expect("restarted content"),
    );

    let first_id = first.next_request_id();
    let restarted_id = restarted.next_request_id();
    assert!(first_id.starts_with("dfs_net_req_1_"), "{first_id}");
    assert!(restarted_id.starts_with("dfs_net_req_1_"), "{restarted_id}");
    assert_ne!(first_id, restarted_id);
    std::fs::remove_dir_all(first_root).ok();
    std::fs::remove_dir_all(restarted_root).ok();
}

#[test]
fn sifs_bootstrap_repairs_untraversable_legacy_system_directories() {
    let root = temp_root("sifs-bootstrap-legacy-zero-mode");
    let node = NodeId::from_legacy_named("node_sifs_bootstrap_legacy_mode").expect("node");
    let content = LocalContentStore::new(root.join("content")).expect("content store");
    let mut dfs = NetworkedDfsService::new(ReceiveOnlyTransport::new(node), content);
    dfs.bootstrap_distributed_sifs().expect("bootstrap SIFS");
    for path in ["/", "/sinomo"] {
        let mut legacy = crate::namespace::directory_object(path, dfs.node_id().clone());
        legacy.mode = 0;
        dfs.add_object_metadata(legacy)
            .expect("seed legacy bootstrap directory");
    }
    assert_eq!(dfs.posix_stat("/").expect("zero root").mode, 0);
    assert_eq!(dfs.posix_stat("/sinomo").expect("zero sinomo").mode, 0);

    dfs.bootstrap_distributed_sifs()
        .expect("repair SIFS bootstrap modes");

    assert_eq!(dfs.posix_stat("/").expect("root").mode, 0o755);
    assert_eq!(dfs.posix_stat("/sinomo").expect("sinomo").mode, 0o755);

    dfs.posix_set_mode("/sinomo", 0)
        .expect("intentional chmod after migration");
    dfs.bootstrap_distributed_sifs()
        .expect("re-bootstrap after intentional chmod");
    assert_eq!(
        dfs.posix_stat("/sinomo").expect("intentional mode").mode,
        0,
        "bootstrap must not mistake a real chmod(000) for legacy metadata"
    );
    std::fs::remove_dir_all(root).ok();
}

