#[test]
fn served_message_transport_sends_nested_return_node_requests_synchronously() {
    let primary = NodeId::from_legacy_named("node_served_nested_primary").expect("primary");
    let requester = NodeId::from_legacy_named("node_served_nested_requester").expect("requester");
    let sent_requests = Arc::new(Mutex::new(Vec::new()));
    let sender_requests = Arc::clone(&sent_requests);
    let sender_primary = primary.clone();
    let sender_requester = requester.clone();
    let sender: DfsMessageSender = Arc::new(move |target, command, _timeout| {
        assert_eq!(target, &sender_requester);
        sender_requests
            .lock()
            .expect("sent requests")
            .push(command.request_id.clone());
        let DfsNetworkMessage::NamespaceRequest(nested) = &command.routed_message.message else {
            panic!(
                "expected nested namespace request, got {:?}",
                command.routed_message.message
            );
        };
        Ok(DfsMessageResponse {
            request_id: command.request_id.clone(),
            outbound_messages: vec![build_dfs_routed_message(
                &sender_requester,
                &sender_primary,
                command.routed_message.frame_id + 100,
                command.routed_message.message_id + 100,
                DfsNetworkMessage::NamespaceResponse(DfsNamespaceResponse {
                    request_id: nested.request_id.clone(),
                    result: DfsNamespaceResult::Applied,
                    synced_path_object: None,
                    synced_path_objects: Vec::new(),
                    metadata_journal_batches: Vec::new(),
                    posix_coordination_result: None,
                }),
            )],
        })
    });
    let mut transport = DfsNodeServedMessageTransport::new_with_message_sender(
        primary.clone(),
        vec![requester.clone()],
        sender,
        sinomo_core::network::DEFAULT_NETWORK_TIMEOUT,
    );
    let served = test_dfs_lookup_routed_message(&requester, &primary, 1, "/services/served");
    transport
        .begin_message(&served)
        .expect("begin served message");

    transport
        .send_routed_call(
            &requester,
            DfsRoutedCall::value(build_dfs_routed_message(
                &primary,
                &requester,
                2,
                2,
                DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
                    request_id: "dfs_net_req_nested_return_node".to_string(),
                    file_system_id: sifs_file_system_id(),
                    requesting_node_id: primary.clone(),
                    include_metadata_journal_batches: false,
                    metadata_journal_after_sequences: Vec::new(),
                    authority_shards: Vec::new(),
                    operation: DfsNamespaceOperation::TouchDirectoryModified {
                        path: "/services".to_string(),
                    },
                }),
            )),
        )
        .expect("nested return-node request should be sent synchronously");

    assert_eq!(
        sent_requests.lock().expect("sent requests").as_slice(),
        ["dfs_message_2"],
        "nested return-node requests must be sent as calls, not returned as the original call response"
    );
    let incoming = transport
        .drain_incoming_messages()
        .expect("returned nested response");
    assert_eq!(incoming.len(), 1);
    assert!(matches!(
        incoming[0].message,
        DfsNetworkMessage::NamespaceResponse(_)
    ));
    assert!(
        transport.finish_message().is_empty(),
        "nested request responses are processed as incoming work, not returned as original RPC outbound messages"
    );
}

#[test]
fn served_message_transport_returns_response_frames_to_caller() {
    let primary = NodeId::from_legacy_named("node_served_return_primary").expect("primary");
    let requester = NodeId::from_legacy_named("node_served_return_requester").expect("requester");
    let sent_requests = Arc::new(AtomicUsize::new(0));
    let sender_count = Arc::clone(&sent_requests);
    let sender: DfsMessageSender = Arc::new(move |_target, _command, _timeout| {
        sender_count.fetch_add(1, Ordering::SeqCst);
        Ok(DfsMessageResponse {
            request_id: "unexpected".to_string(),
            outbound_messages: Vec::new(),
        })
    });
    let mut transport = DfsNodeServedMessageTransport::new_with_message_sender(
        primary.clone(),
        vec![requester.clone()],
        sender,
        sinomo_core::network::DEFAULT_NETWORK_TIMEOUT,
    );
    let served = test_dfs_lookup_routed_message(&requester, &primary, 3, "/services/served");
    transport
        .begin_message(&served)
        .expect("begin served message");

    transport
        .send_routed_call(
            &requester,
            DfsRoutedCall::value(build_dfs_routed_message(
                &primary,
                &requester,
                4,
                4,
                DfsNetworkMessage::NamespaceResponse(DfsNamespaceResponse {
                    request_id: "dfs_net_req_returned_response".to_string(),
                    result: DfsNamespaceResult::Applied,
                    synced_path_object: None,
                    synced_path_objects: Vec::new(),
                    metadata_journal_batches: Vec::new(),
                    posix_coordination_result: None,
                }),
            )),
        )
        .expect("response frame should return to the caller");

    assert_eq!(sent_requests.load(Ordering::SeqCst), 0);
    let outbound = transport.finish_message();
    assert_eq!(outbound.len(), 1);
    assert!(matches!(
        outbound[0].message,
        DfsNetworkMessage::NamespaceResponse(_)
    ));
}

#[test]
fn dfs_service_advertisements_use_node_identity_only() {
    let node = NodeId::from_legacy_named("node_dfs_service_advertisement_node_only").expect("node");

    let metadata = DfsNodeAdvertisement::metadata(node.clone());
    let content = DfsNodeAdvertisement::content(node.clone());

    assert_eq!(metadata.node_id, node);
    assert!(metadata.accepts_metadata);
    assert!(!metadata.accepts_content);
    assert_eq!(content.node_id, metadata.node_id);
    assert!(!content.accepts_metadata);
    assert!(content.accepts_content);
}

#[test]
fn routed_namespace_sync_drains_limited_response_backlog() {
    let writer = NodeId::from_legacy_named("node_routed_sync_writer").expect("writer");
    let primary = NodeId::from_legacy_named("node_routed_sync_primary").expect("primary");
    let file_system_id = sifs_file_system_id();
    let root = temp_root("routed_namespace_sync_synced_path_backlog");
    let control_plane = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    control_plane.with_client(|kv| {
        DfsControlPlaneStore::new(kv)
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: file_system_id.clone(),
                shard_id: "services".to_string(),
                primary_node_id: primary.clone(),
                replica_node_ids: vec![writer.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::PathPrefix {
                    prefix: "/services".to_string(),
                },
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("metadata shard");
    });
    let primary_sender: DfsMessageSender = Arc::new(|target_node_id, command, _timeout| {
        Err(DfsPeerTransportError::new(format!(
            "unexpected primary-side send to {target_node_id} for {}",
            command.request_id
        )))
    });
    let primary_transport = DfsNodeServedMessageTransport::new_with_message_sender(
        primary.clone(),
        vec![writer.clone()],
        primary_sender,
        sinomo_core::network::DEFAULT_NETWORK_TIMEOUT,
    );
    let primary_backend = LocalSobjMetadataBackend::new(
        DfsMetadataShardId::new("services"),
        root.join("primary-metadata"),
    )
    .expect("primary metadata backend");
    let mut primary_service = NetworkedDfsService::new(
        primary_transport,
        LocalContentStore::new(root.join("primary-content")).expect("primary content"),
    )
    .with_control_plane(control_plane.clone())
    .with_metadata_backend(primary_backend)
    .expect("primary metadata");
    primary_service
        .bootstrap_distributed_sifs()
        .expect("primary bootstrap");
    let services_shard_id = DfsMetadataShardId::new("services");
    let bootstrap_sequence = primary_service
        .metadata_backend()
        .expect("primary metadata backend")
        .journal_last_sequence()
        .expect("primary bootstrap journal head");
    let bootstrap_snapshot = primary_service
        .metadata_backend()
        .expect("primary metadata backend")
        .export_shard_table_snapshot(&services_shard_id)
        .expect("primary bootstrap snapshot")
        .expect("services bootstrap snapshot");
    for index in 0..(DEFAULT_METADATA_JOURNAL_BATCH_ENTRY_LIMIT + 8) {
        let mut object = file_metadata(primary.clone());
        object.object_id =
            DfsObjectId::from_legacy_named(format!("obj_routed_sync_backlog_{index}"))
                .expect("object");
        object.path = format!("/services/backlog-seed-{index}.txt");
        object.version =
            DfsVersion::from_legacy_named(format!("version_routed_sync_{index}")).expect("version");
        object.content_hash = Some(format!("blake3:routed-sync-{index}"));
        object.content_size_bytes = Some(index as u64);
        object.policy = DfsObjectPolicy::ReplicatedEventual;
        primary_service
            .add_object_metadata(object)
            .expect("primary backlog object");
    }
    let primary_service = Arc::new(Mutex::new(primary_service));
    let namespace_calls = Arc::new(Mutex::new(Vec::new()));
    let mkdir_all_response_batches = Arc::new(Mutex::new(Vec::new()));
    let primary_for_sender = primary.clone();
    let primary_service_for_sender = Arc::clone(&primary_service);
    let namespace_calls_for_sender = Arc::clone(&namespace_calls);
    let mkdir_all_response_batches_for_sender = Arc::clone(&mkdir_all_response_batches);
    let writer_sender: DfsMessageSender = Arc::new(move |target_node_id, command, _timeout| {
        if target_node_id != &primary_for_sender {
            return Err(DfsPeerTransportError::new(format!(
                "unexpected target {target_node_id}"
            )));
        }
        std::thread::sleep(Duration::from_millis(10));
        let capture_mkdir_all_response = match &command.routed_message.message {
            DfsNetworkMessage::NamespaceRequest(namespace) => {
                matches!(&namespace.operation, DfsNamespaceOperation::MkdirAll { .. })
            }
            _ => false,
        };
        if let DfsNetworkMessage::NamespaceRequest(namespace) = &command.routed_message.message {
            let label = match &namespace.operation {
                DfsNamespaceOperation::MkdirAll { .. } => "mkdir-all",
                DfsNamespaceOperation::SyncPath { .. } => "sync-path",
                _ => "other-namespace",
            };
            namespace_calls_for_sender
                .lock()
                .expect("namespace calls")
                .push(label.to_string());
        }
        let result = primary_service_for_sender
            .lock()
            .expect("primary service")
            .process_message_command(command.clone())
            .map_err(|error| DfsPeerTransportError::new(error.to_string()))?;
        if capture_mkdir_all_response {
            let mut captured_batches = mkdir_all_response_batches_for_sender
                .lock()
                .expect("mkdir-all response batches");
            for outbound in &result.response.outbound_messages {
                let DfsNetworkMessage::NamespaceResponse(response) = &outbound.message else {
                    continue;
                };
                for batch in &response.metadata_journal_batches {
                    let encoded_bytes =
                        crate::metadata_journal::metadata_journal_batch_encoded_len(batch)
                            .map_err(|error| DfsPeerTransportError::new(error.to_string()))?;
                    captured_batches.push((batch.entries.len(), encoded_bytes));
                }
            }
        }
        Ok(result.response)
    });
    let writer_transport = DfsNodeTransport::with_message_sender_for_nodes(
        writer.clone(),
        vec![primary.clone()],
        Duration::from_millis(20),
        writer_sender,
    );
    let mut writer_backend =
        LocalSobjMetadataBackend::new(services_shard_id.clone(), root.join("writer-metadata"))
            .expect("writer metadata backend");
    writer_backend
        .replace_with_replicated_snapshot(services_shard_id, bootstrap_sequence, bootstrap_snapshot)
        .expect("seed writer from replicated bootstrap prefix");
    let mut writer_service = NetworkedDfsService::new(
        writer_transport,
        LocalContentStore::new(root.join("writer-content")).expect("writer content"),
    )
    .with_control_plane(control_plane)
    .with_metadata_backend(writer_backend)
    .expect("attach writer metadata replica");
    writer_service
        .posix_mkdir_all("/services/routed-sync-backlog/new-dir")
        .expect("routed mkdir should drain bounded response backlog");

    assert_eq!(
        DFS_ROUTED_NAMESPACE_RESPONSE_JOURNAL_ENTRY_LIMIT, 2048,
        "namespace catch-up should request the larger entry cap"
    );
    assert_eq!(
        DFS_ROUTED_NAMESPACE_RESPONSE_JOURNAL_BYTE_LIMIT, DEFAULT_METADATA_JOURNAL_BATCH_BYTE_LIMIT,
        "namespace catch-up must retain the ordinary 4 MiB encoded-byte bound"
    );
    let response_batches = mkdir_all_response_batches
        .lock()
        .expect("mkdir-all response batches")
        .clone();
    assert_eq!(
        response_batches.len(),
        DFS_ROUTED_NAMESPACE_RESPONSE_JOURNAL_BATCH_LIMIT,
        "the namespace response should still carry only one journal batch"
    );
    let (entry_count, encoded_bytes) = response_batches[0];
    assert!(
        entry_count > DEFAULT_METADATA_JOURNAL_BATCH_ENTRY_LIMIT,
        "the namespace response should pack past the ordinary 512-entry cap"
    );
    assert!(
        entry_count <= DFS_ROUTED_NAMESPACE_RESPONSE_JOURNAL_ENTRY_LIMIT,
        "the namespace response exceeded its 2048-entry cap"
    );
    assert!(
        encoded_bytes <= DFS_ROUTED_NAMESPACE_RESPONSE_JOURNAL_BYTE_LIMIT,
        "the namespace response exceeded its 4 MiB encoded-byte cap"
    );

    let calls = namespace_calls.lock().expect("namespace calls").clone();
    assert_eq!(
        calls.first().map(String::as_str),
        Some("mkdir-all"),
        "the mutating operation should be sent first"
    );
    assert!(
        calls.iter().any(|call| call == "sync-path"),
        "bounded response replay should continue with follow-up sync-path calls"
    );
    assert!(
        writer_service
            .posix_stat(&format!(
                "/services/backlog-seed-{}.txt",
                DEFAULT_METADATA_JOURNAL_BATCH_ENTRY_LIMIT + 7
            ))
            .is_ok(),
        "latest backlog entry should be visible after routed mkdir returns"
    );
}

#[derive(Default)]
struct RecordingPeerTransport {
    calls: Mutex<Vec<String>>,
    options: Mutex<Vec<(String, bool)>>,
}

impl DfsPeerTransport for RecordingPeerTransport {
    fn call_object_rpc(
        &self,
        target_node_id: &NodeId,
        call: ObjectRpcSessionCall,
        options: DfsObjectRpcSendOptions,
    ) -> Result<ObjectRpcSessionResult, DfsPeerTransportError> {
        if !call.body.is_empty() {
            return Err(DfsPeerTransportError::new(
                "recording peer does not accept an attachment",
            ));
        }
        let request = &call.request;
        self.options
            .lock()
            .expect("options")
            .push((request.route.clone(), options.observe_connectivity));
        let response = match request.route.as_str() {
            route if dfs_route_is_message_data_plane(route) => {
                let command: DfsMessageCommand = request
                    .decode_body()
                    .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
                self.calls.lock().expect("calls").push(format!(
                    "rpc:{}:{}:{}",
                    request.route, target_node_id, command.request_id
                ));
                ObjectRpcResponse::encode_body(
                    route,
                    &DfsMessageResponse {
                        request_id: command.request_id,
                        outbound_messages: Vec::new(),
                    },
                )
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))
            }
            DFS_DIRECT_READ_ROUTE => {
                let command: DfsDirectReadRequest = request
                    .decode_body()
                    .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
                self.calls.lock().expect("calls").push(format!(
                    "rpc:{}:{}:{}",
                    request.route, target_node_id, command.request_id
                ));
                return dfs_direct_read_rpc_session_result(DfsReadResponse {
                    request_id: command.request_id,
                    object_id: command.object_id.clone(),
                    result: DfsReadResult::Found(DfsReadData {
                        object_id: command.object_id,
                        version: command.version,
                        content_hash: Some(command.content_hash),
                        bytes: vec![1, 2, 3],
                    }),
                })
                .map_err(|source| DfsPeerTransportError::new(source.to_string()));
            }
            DFS_METADATA_JOURNAL_BATCH_ROUTE => {
                let command: DfsMetadataJournalBatchCommand = request
                    .decode_body()
                    .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
                self.calls.lock().expect("calls").push(format!(
                    "rpc:{}:{}:{}",
                    request.route, target_node_id, command.request_id
                ));
                ObjectRpcResponse::encode_body(
                    DFS_METADATA_JOURNAL_BATCH_ROUTE,
                    &DfsMetadataJournalBatchResponse {
                        request_id: command.request_id,
                        shard_id: command.batch.shard_id,
                        next_after_sequence: command.batch.next_after_sequence,
                        applied_entries: command.batch.entries.len(),
                        verified_prefix_only: command.verify_prefix_only,
                        verified_authority_probe_id: None,
                        result: DfsMetadataJournalBatchResult::Applied,
                    },
                )
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))
            }
            DFS_METADATA_SNAPSHOT_INSTALL_ROUTE => {
                let command: DfsMetadataSnapshotInstallCommand = request
                    .decode_body()
                    .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
                self.calls.lock().expect("calls").push(format!(
                    "rpc:{}:{}:{}",
                    request.route, target_node_id, command.request_id
                ));
                ObjectRpcResponse::encode_body(
                    DFS_METADATA_SNAPSHOT_INSTALL_ROUTE,
                    &DfsMetadataSnapshotInstallResponse {
                        request_id: command.request_id,
                        shard_id: command.shard_id,
                        next_after_sequence: command.next_after_sequence,
                        result: DfsMetadataSnapshotInstallResult::Installed {
                            archived_existing: false,
                        },
                    },
                )
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))
            }
            other => Err(DfsPeerTransportError::new(format!(
                "unexpected DFS object RPC route {other}"
            ))),
        }?;
        Ok(ObjectRpcSessionResult::value(response))
    }
}

impl AsyncDfsPeerTransport for RecordingPeerTransport {
    fn call_object_rpc_async<'a>(
        &'a self,
        target_node_id: &'a NodeId,
        call: ObjectRpcSessionCall,
        options: DfsObjectRpcSendOptions,
    ) -> DfsPeerTransportFuture<'a, Result<ObjectRpcSessionResult, DfsPeerTransportError>> {
        Box::pin(async move { self.call_object_rpc(target_node_id, call, options) })
    }
}

#[derive(Default)]
struct ConcurrentMetadataPeerTransport {
    active_calls: AtomicUsize,
    max_active_calls: AtomicUsize,
}

impl DfsPeerTransport for ConcurrentMetadataPeerTransport {
    fn call_object_rpc(
        &self,
        _target_node_id: &NodeId,
        call: ObjectRpcSessionCall,
        _options: DfsObjectRpcSendOptions,
    ) -> Result<ObjectRpcSessionResult, DfsPeerTransportError> {
        if !call.body.is_empty() {
            return Err(DfsPeerTransportError::new(
                "metadata peer does not accept an attachment",
            ));
        }
        let request = &call.request;
        let active = self.active_calls.fetch_add(1, Ordering::SeqCst) + 1;
        self.max_active_calls.fetch_max(active, Ordering::SeqCst);
        // Yield the worker long enough for the other scoped workers to enter.
        // A sequential implementation can never observe more than one active
        // call, independent of machine speed.
        std::thread::sleep(Duration::from_millis(25));
        self.active_calls.fetch_sub(1, Ordering::SeqCst);

        let command: DfsMetadataJournalBatchCommand = request
            .decode_body()
            .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
        let verified_authority_probe_id = command
            .authority_probe
            .as_ref()
            .and_then(crate::service_replica::metadata_authority_probe_confirmation_id);
        ObjectRpcResponse::encode_body(
            DFS_METADATA_JOURNAL_BATCH_ROUTE,
            &DfsMetadataJournalBatchResponse {
                request_id: command.request_id,
                shard_id: command.batch.shard_id,
                next_after_sequence: command.batch.next_after_sequence,
                applied_entries: command.batch.entries.len(),
                verified_prefix_only: command.verify_prefix_only,
                verified_authority_probe_id,
                result: DfsMetadataJournalBatchResult::Applied,
            },
        )
        .map(ObjectRpcSessionResult::value)
        .map_err(|source| DfsPeerTransportError::new(source.to_string()))
    }
}

fn recording_async_peer_transport(
    peer: Arc<RecordingPeerTransport>,
) -> Arc<dyn AsyncDfsPeerTransport> {
    peer
}

#[test]
fn dfs_peer_transport_adapters_delegate_all_routes() {
    let peer = Arc::new(RecordingPeerTransport::default());
    let peer_transport: Arc<dyn DfsPeerTransport> = peer.clone();
    let message_sender = dfs_message_sender_from_peer_transport(Arc::clone(&peer_transport));
    let journal_sender =
        dfs_metadata_journal_batch_sender_from_peer_transport(Arc::clone(&peer_transport));
    let snapshot_sender = dfs_metadata_snapshot_install_sender_from_peer_transport(peer_transport);
    let local = NodeId::from_legacy_named("node_dfs_peer_transport_local").expect("local");
    let remote = NodeId::from_legacy_named("node_dfs_peer_transport_remote").expect("remote");
    let routed_message = build_dfs_routed_message(
        &local,
        &remote,
        42,
        42,
        DfsNetworkMessage::ReadRequest(DfsReadRequest {
            request_id: "read-1".to_string(),
            object_id: DfsObjectId::generate(),
            version: None,
            content_hash: None,
            content_size_bytes: None,
            range_offset: None,
            range_max_bytes: None,
        }),
    );

    message_sender(
        &remote,
        &DfsMessageCommand {
            request_id: "protocol-1".to_string(),
            routed_message,
        },
        DfsObjectRpcSendOptions::new(Duration::from_secs(1)),
    )
    .expect("message send");

    let shard_id = DfsMetadataShardId::new("root");
    journal_sender(
        &remote,
        &DfsMetadataJournalBatchCommand {
            request_id: "journal-1".to_string(),
            source_node_id: Some(local.clone()),
            file_system_id: None,
            authority_epoch: None,
            verify_prefix_only: false,
            prefix_probe: None,
            authority_probe: None,
            batch: DfsMetadataJournalBatch {
                shard_id: shard_id.clone(),
                entries: Vec::new(),
                next_after_sequence: 0,
            },
        },
        Duration::from_secs(1),
    )
    .expect("journal send");

    let snapshot_root = temp_root("dfs_peer_transport_snapshot");
    let snapshot = LocalSobjMetadataBackend::new(shard_id.clone(), &snapshot_root)
        .expect("metadata backend")
        .export_table_snapshot();
    snapshot_sender(
        &remote,
        &DfsMetadataSnapshotInstallCommand {
            request_id: "snapshot-1".to_string(),
            source_node_id: local,
            file_system_id: None,
            authority_epoch: None,
            shard_id,
            next_after_sequence: 0,
            snapshot,
            reason: "test".to_string(),
        },
        Duration::from_secs(1),
    )
    .expect("snapshot send");

    assert_eq!(
        peer.calls.lock().expect("calls").as_slice(),
        &[
            format!("rpc:/dfs/data/read:{remote}:protocol-1"),
            format!("rpc:/dfs/metadata/journal-batch:{remote}:journal-1"),
            format!("rpc:/dfs/metadata/snapshot-install:{remote}:snapshot-1"),
        ]
    );
    std::fs::remove_dir_all(snapshot_root).ok();
}

#[test]
fn direct_authority_probe_uses_canonical_route_and_old_peer_fails_closed() {
    let local = NodeId::from_legacy_named("node_direct_authority_local").expect("local");
    let remote = NodeId::from_legacy_named("node_direct_authority_remote").expect("remote");
    let file_system = distributed_sifs(local.clone());
    let shard = DfsMetadataShardConfig {
        file_system_id: file_system.file_system_id.clone(),
        shard_id: "root".to_string(),
        primary_node_id: local.clone(),
        replica_node_ids: vec![remote.clone()],
        epoch: 7,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    let source_root = temp_root("direct-authority-route-source");
    let mut source = LocalSobjMetadataBackend::new(
        DfsMetadataShardId::new(shard.shard_id.clone()),
        &source_root,
    )
    .expect("source metadata backend");
    source
        .put_file_system(&file_system)
        .expect("source filesystem");
    let batch = source
        .journal_batch_since_limited(
            0,
            DEFAULT_METADATA_JOURNAL_BATCH_ENTRY_LIMIT,
            DEFAULT_METADATA_JOURNAL_BATCH_BYTE_LIMIT,
        )
        .expect("source journal")
        .expect("source journal batch");
    let command = DfsMetadataJournalBatchCommand {
        request_id: "direct-authority-request".to_string(),
        source_node_id: Some(local.clone()),
        file_system_id: Some(shard.file_system_id.clone()),
        authority_epoch: Some(shard.epoch),
        verify_prefix_only: false,
        prefix_probe: None,
        authority_probe: Some(DfsMetadataAuthorityProbe {
            probe_id: "direct-authority-probe".to_string(),
            expected_shard: shard.clone(),
            operation: DfsMetadataAuthorityOperation::NamespaceMutation {
                operation_id: "direct-authority-operation".to_string(),
                file_system_id: shard.file_system_id.clone(),
                prepare_sequence: batch.next_after_sequence,
                payload_digest: "blake3:direct-authority-operation".to_string(),
            },
            prepared_prefix: None,
        }),
        batch,
    };

    let peer = Arc::new(RecordingPeerTransport::default());
    let peer_transport: Arc<dyn DfsPeerTransport> = peer.clone();
    let async_peer_transport = recording_async_peer_transport(Arc::clone(&peer));
    let mut transport = DfsNodeTransport::with_peer_transports_for_nodes(
        local.clone(),
        vec![remote.clone()],
        Duration::from_secs(1),
        peer_transport,
        async_peer_transport,
    );
    let response = transport
        .send_metadata_journal_batch_direct(&remote, &command)
        .expect("direct metadata route")
        .expect("production node transport supports direct metadata route");
    assert_eq!(response.verified_authority_probe_id, None);
    assert_eq!(
        peer.calls.lock().expect("calls").as_slice(),
        &[format!(
            "rpc:/dfs/metadata/journal-batch:{remote}:direct-authority-request"
        )]
    );

    let served_peer = Arc::new(RecordingPeerTransport::default());
    let served_peer_transport: Arc<dyn DfsPeerTransport> = served_peer.clone();
    let mut served = DfsNodeServedMessageTransport::new_with_peer_transport_for_nodes(
        local,
        vec![remote.clone()],
        served_peer_transport,
        Duration::from_secs(1),
    );
    let response = served
        .send_metadata_journal_batch_direct(&remote, &command)
        .expect("served direct metadata route")
        .expect("production served transport retains direct peer transport");
    assert_eq!(response.verified_authority_probe_id, None);
    assert_eq!(
        served_peer.calls.lock().expect("calls").as_slice(),
        &[format!(
            "rpc:/dfs/metadata/journal-batch:{remote}:direct-authority-request"
        )]
    );
    std::fs::remove_dir_all(source_root).ok();
}

#[test]
fn direct_metadata_authority_fans_out_to_replicas_concurrently() {
    let local = NodeId::from_legacy_named("node_direct_fanout_local").expect("local");
    let remotes = (0..3)
        .map(|index| {
            NodeId::from_legacy_named(format!("node_direct_fanout_remote_{index}")).expect("remote")
        })
        .collect::<Vec<_>>();
    let peer = Arc::new(ConcurrentMetadataPeerTransport::default());
    let peer_transport: Arc<dyn DfsPeerTransport> = peer.clone();
    let mut transport = DfsNodeServedMessageTransport::new_with_peer_transport_for_nodes(
        local.clone(),
        remotes.clone(),
        peer_transport,
        Duration::from_secs(1),
    );
    let shard_id = DfsMetadataShardId::new("root");
    let requests = remotes
        .iter()
        .enumerate()
        .map(|(index, remote)| {
            (
                remote.clone(),
                DfsMetadataJournalBatchCommand {
                    request_id: format!("direct-fanout-{index}"),
                    source_node_id: Some(local.clone()),
                    file_system_id: None,
                    authority_epoch: None,
                    verify_prefix_only: false,
                    prefix_probe: None,
                    authority_probe: None,
                    batch: DfsMetadataJournalBatch {
                        shard_id: shard_id.clone(),
                        entries: Vec::new(),
                        next_after_sequence: 9,
                    },
                },
            )
        })
        .collect::<Vec<_>>();

    let responses = transport
        .send_metadata_journal_batches_direct(&requests)
        .expect("direct fan-out")
        .expect("peer transport retained");

    assert_eq!(responses.len(), remotes.len());
    assert!(
        peer.max_active_calls.load(Ordering::SeqCst) >= 2,
        "metadata authority RPCs must overlap instead of adding replica RTTs"
    );
}

#[test]
fn dfs_direct_read_peer_transport_adapters_observe_connectivity() {
    let remote = NodeId::from_legacy_named("node_dfs_direct_read_observe_remote").expect("remote");
    let expected_bytes = [1, 2, 3];
    let request = DfsDirectReadRequest {
        request_id: "direct-observe-1".to_string(),
        object_id: DfsObjectId::generate(),
        version: DfsVersion::generate(),
        content_hash: content_hash(&expected_bytes),
        content_size_bytes: expected_bytes.len() as u64,
    };

    let peer = Arc::new(RecordingPeerTransport::default());
    let peer_transport: Arc<dyn DfsPeerTransport> = peer.clone();
    let direct_sender = dfs_direct_read_sender_from_peer_transport(peer_transport);
    direct_sender(
        &remote,
        &request,
        DfsObjectRpcSendOptions::new(Duration::from_secs(1)),
    )
    .expect("direct read send");
    assert_eq!(
        peer.options.lock().expect("options").as_slice(),
        &[(DFS_DIRECT_READ_ROUTE.to_string(), true)]
    );

    let async_peer = Arc::new(RecordingPeerTransport::default());
    let async_peer_transport: Arc<dyn AsyncDfsPeerTransport> = async_peer.clone();
    let async_direct_sender =
        async_dfs_direct_read_sender_from_peer_transport(async_peer_transport);
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_time()
        .build()
        .expect("runtime");
    runtime
        .block_on(async {
            async_direct_sender(
                &remote,
                &request,
                DfsObjectRpcSendOptions::new(Duration::from_secs(1)),
            )
            .await
        })
        .expect("async direct read send");
    assert_eq!(
        async_peer.options.lock().expect("options").as_slice(),
        &[(DFS_DIRECT_READ_ROUTE.to_string(), true)]
    );
}

impl DfsTransportIdentity for CountingEmptyTransport {
    fn local_node_id(&self) -> &NodeId {
        &self.local_node_id
    }
}

impl DfsMessageTransport for CountingEmptyTransport {
    fn send_routed_call(
        &mut self,
        target_node_id: &NodeId,
        _call: DfsRoutedCall,
    ) -> Result<(), NetworkError> {
        Err(NetworkError::UnknownNode {
            node_id: target_node_id.clone(),
        })
    }

    fn drain_incoming_messages(&mut self) -> Result<Vec<DfsRoutedMessage>, NetworkError> {
        *self.drain_calls.lock().expect("drain calls") += 1;
        Ok(Vec::new())
    }

    fn pending_incoming_count(&self) -> Result<Option<usize>, NetworkError> {
        Ok(Some(0))
    }
}

