#[test]
fn routed_namespace_redirect_corroborates_only_the_dispatch_shard_successor() {
    let root = temp_root("routed-namespace-cross-shard-redirect-corroboration");
    let requester =
        NodeId::from_legacy_named("node_namespace_redirect_requester").expect("requester");
    let retired_dispatch =
        NodeId::from_legacy_named("node_namespace_redirect_retired").expect("retired dispatch");
    let current_dispatch =
        NodeId::from_legacy_named("node_namespace_redirect_current").expect("current dispatch");
    let foreign_primary =
        NodeId::from_legacy_named("node_namespace_redirect_foreign").expect("foreign primary");

    let mut dispatch_authority = test_routed_authority_shard(&retired_dispatch, 3);
    dispatch_authority.shard_id = "users".to_string();
    dispatch_authority.assignment = DfsMetadataShardAssignment::PathPrefix {
        prefix: SIFS_USERS_PATH.to_string(),
    };
    let mut current_dispatch_authority = dispatch_authority.clone();
    current_dispatch_authority.primary_node_id = current_dispatch.clone();
    current_dispatch_authority.epoch = 4;
    let foreign_authority = test_routed_authority_shard(&foreign_primary, 9);

    let control_plane = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    control_plane.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_metadata_shard(&current_dispatch_authority)
            .expect("current dispatch authority");
        control
            .put_metadata_shard(&foreign_authority)
            .expect("unchanged foreign authority");
    });
    let mut dfs = NetworkedDfsService::new(
        DroppingSendTransport {
            local_node_id: requester,
        },
        LocalContentStore::new(root.join("content")).expect("content"),
    )
    .with_control_plane(control_plane);
    dfs.pending_routed_namespace_ops.insert(
        "dfs_net_req_cross_shard_redirect".to_string(),
        PendingRoutedNamespaceOp {
            primary_node_id: retired_dispatch.clone(),
            dispatch_authority_shard: Some(dispatch_authority.clone()),
            authority_shards: vec![dispatch_authority, foreign_authority],
            replay_journal_batches: false,
            apply_synced_path_object: false,
            result: None,
        },
    );

    let event = dfs
        .handle_namespace_response(
            retired_dispatch,
            DfsNamespaceResponse {
                request_id: "dfs_net_req_cross_shard_redirect".to_string(),
                result: DfsNamespaceResult::Rejected {
                    reason: "dispatch authority moved".to_string(),
                    posix_error: None,
                    current_primary_node_id: Some(current_dispatch.clone()),
                },
                synced_path_object: None,
                synced_path_objects: Vec::new(),
                metadata_journal_batches: Vec::new(),
                posix_coordination_result: None,
            },
        )
        .expect("corroborated redirect response");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RemoteNamespaceCompleted {
            result: DfsNamespaceResult::Rejected {
                current_primary_node_id: Some(ref primary),
                ..
            },
            ..
        } if primary == &current_dispatch
    ));
    assert!(matches!(
        dfs.pending_routed_namespace_ops
            .get("dfs_net_req_cross_shard_redirect")
            .and_then(|pending| pending.result.as_ref())
            .map(|settled| &settled.result),
        Some(DfsNamespaceResult::Rejected {
            current_primary_node_id: Some(primary),
            ..
        }) if primary == &current_dispatch
    ));

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn stage_response_commits_restored_pending_intent_without_inflight_request_id() {
    let root = temp_root("stage-response-commits-restored-pending-intent");
    let primary =
        NodeId::from_legacy_named("node_stage_response_restore_primary").expect("primary");
    let replica =
        NodeId::from_legacy_named("node_stage_response_restore_replica").expect("replica");
    let object_id = DfsObjectId::from_legacy_named("obj_stage_response_restore").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_stage_response_restore_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_stage_response_restore_2").expect("version");
    let bytes = b"stage response must survive stateless daemon handling";
    let network = InProcessNetwork::new();
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut dfs = NetworkedDfsService::new(network.add_node(primary.clone()), content)
        .with_metadata_backend(metadata)
        .expect("metadata backend");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut object = file_metadata(primary.clone());
    object.object_id = object_id.clone();
    object.path = "/services/stateless-stage-response.txt".to_string();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![primary.clone()];
    dfs.add_object_metadata(object).expect("object metadata");

    let outcome = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: primary.clone(),
            },
            bytes.to_vec(),
            vec![primary.clone(), replica.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("pending distributed write");
    let NetworkedDfsWriteOutcome::Pending {
        intent_id,
        durable_receipts,
        required_receipts,
    } = outcome
    else {
        panic!("expected pending write, got {outcome:?}");
    };
    assert_eq!(durable_receipts, 1);
    assert_eq!(required_receipts, 2);
    let content_hash = dfs
        .metadata_backend()
        .expect("metadata backend")
        .get_intent(&object_id, &intent_id)
        .expect("intent read")
        .expect("intent")
        .content_hash
        .expect("intent content hash");
    drop(dfs);

    let restarted_network = InProcessNetwork::new();
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut restarted =
        NetworkedDfsService::new(restarted_network.add_node(primary.clone()), content)
            .with_metadata_backend(metadata)
            .expect("restored metadata backend");
    assert!(
        restarted
            .pending_writes
            .get(&intent_id)
            .is_some_and(|pending| pending.stage_inflight_request_ids.is_empty()),
        "restored daemon state should not rely on ephemeral inflight request ids"
    );

    let event = restarted
        .handle_stage_blob_response(
            replica.clone(),
            DfsStageBlobResponse {
                request_id: "lost-daemon-inflight-request-id".to_string(),
                intent_id: intent_id.clone(),
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                version: version_2.clone(),
                replica_node_id: replica.clone(),
                result: DfsBlobTransferResult::Durable {
                    content_hash: content_hash.clone(),
                },
            },
        )
        .expect("stage response")
        .expect("stage event");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::BlobStaged {
            intent_id: ref event_intent_id,
            ref replica_node_id,
            ..
        } if event_intent_id == &intent_id && replica_node_id == &replica
    ));
    assert!(matches!(
        restarted.write_outcome(&intent_id).expect("write outcome"),
        NetworkedDfsWriteOutcome::Committed {
            version,
            content_hash: ref committed_hash,
            ..
        } if version == version_2 && committed_hash == &content_hash
    ));
    let committed = restarted
        .current_read_object_metadata(&object_id)
        .expect("committed object");
    assert_eq!(committed.version, version_2);
    assert_eq!(
        committed.content_hash.as_deref(),
        Some(content_hash.as_str())
    );
    assert!(committed.current_locations.contains(&primary));
    assert!(committed.current_locations.contains(&replica));

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn fetch_receipt_completion_sends_untracked_routed_write_response() {
    let root = temp_root("fetch-receipt-sends-untracked-routed-response");
    let primary =
        NodeId::from_legacy_named("node_fetch_receipt_response_primary").expect("primary");
    let requester =
        NodeId::from_legacy_named("node_fetch_receipt_response_requester").expect("requester");
    let object_id = DfsObjectId::from_legacy_named("obj_fetch_receipt_response").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_fetch_receipt_response_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_fetch_receipt_response_2").expect("version");
    let bytes = b"fetch receipt completion must notify stateless routed writer";
    let network = InProcessNetwork::new();
    let mut requester_mailbox = network.add_node(requester.clone());
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let manifest = content
        .put_object_version(object_id.as_str(), version_2.as_str(), bytes)
        .expect("local fetched content");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut dfs = NetworkedDfsService::new(network.add_node(primary.clone()), content)
        .with_metadata_backend(metadata)
        .expect("metadata backend");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut object = file_metadata(primary.clone());
    object.object_id = object_id.clone();
    object.path = "/services/stateless-fetch-response.txt".to_string();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![requester.clone()];
    dfs.add_object_metadata(object).expect("object metadata");

    let outcome = dfs
        .write_distributed_eventual_from_remote_manifest_with_base(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: requester.clone(),
            },
            Some(version_1),
            manifest.content_hash.clone(),
            manifest.size_bytes,
            vec![requester.clone(), primary.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
            true,
        )
        .expect("pending remote-manifest write");
    let NetworkedDfsWriteOutcome::Pending {
        intent_id,
        durable_receipts,
        required_receipts,
    } = outcome
    else {
        panic!("expected pending write, got {outcome:?}");
    };
    assert_eq!(durable_receipts, 1);
    assert_eq!(required_receipts, 2);
    let _ = drain_dfs_messages(&mut requester_mailbox);

    dfs.record_local_pending_write_receipt_if_desired(
        &intent_id,
        &object_id,
        &version_2,
        &manifest.content_hash,
    )
    .expect("record local fetched receipt");

    let messages = drain_dfs_messages(&mut requester_mailbox);
    assert!(
        messages.iter().any(|message| {
            matches!(
                message,
                DfsNetworkMessage::DistributedWriteResponse(DfsDistributedWriteResponse {
                    request_id,
                    object_id: response_object_id,
                    result:
                        DfsDistributedWriteResult::Outcome {
                            outcome:
                                NetworkedDfsWriteOutcome::Committed {
                                    intent_id: response_intent_id,
                                    version,
                                    content_hash,
                                    ..
                                },
                        },
                    ..
                }) if request_id == &intent_id
                    && response_intent_id == &intent_id
                    && response_object_id == &object_id
                    && version == &version_2
                    && content_hash == &manifest.content_hash
            )
        }),
        "primary must notify the routed requester after local fetch receipt commits, got {messages:?}"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn routed_inline_blob_records_requester_receipt_without_restaging() {
    let root = temp_root("routed-inline-records-requester-receipt");
    let primary = NodeId::from_legacy_named("node_routed_inline_receipt_primary").expect("primary");
    let writer = NodeId::from_legacy_named("node_routed_inline_receipt_writer").expect("writer");
    let object_id = DfsObjectId::from_legacy_named("obj_routed_inline_receipt").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_routed_inline_receipt_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_routed_inline_receipt_2").expect("version");
    let network = InProcessNetwork::new();
    let mut writer_mailbox = network.add_node(writer.clone());
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let mut dfs = NetworkedDfsService::new(network.add_node(primary.clone()), content);
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut object = file_metadata(primary.clone());
    object.object_id = object_id.clone();
    object.path = "/services/routed-inline-receipt.bin".to_string();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![writer.clone()];
    dfs.add_object_metadata(object).expect("object metadata");

    let outcome = dfs
        .write_distributed_eventual_with_base(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: writer.clone(),
            },
            Some(version_1),
            b"complete inline routed bytes".to_vec(),
            vec![writer.clone(), primary.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("inline routed write");

    assert!(
        matches!(
            &outcome,
            NetworkedDfsWriteOutcome::Committed {
                version,
                repair_jobs,
                ..
            } if version == &version_2 && repair_jobs.is_empty()
        ),
        "primary should commit from requester+primary receipts without repair: {outcome:?}"
    );
    let writer_messages = drain_dfs_messages(&mut writer_mailbox);
    assert!(
        writer_messages.iter().all(|message| {
            !matches!(
                message,
                DfsNetworkMessage::StageBlob(_)
                    | DfsNetworkMessage::FetchBlob(_)
                    | DfsNetworkMessage::FetchBlobResponse(_)
            )
        }),
        "primary must not transfer inline blob bytes back to the requester: {writer_messages:?}"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn posix_non_foreground_write_reports_only_durable_locations() {
    let root = temp_root("posix-non-foreground-current-locations");
    let local = NodeId::from_legacy_named("node_posix_async_repair_local").expect("local node");
    let remote = NodeId::from_legacy_named("node_posix_async_repair_remote").expect("remote node");
    let mut dfs = networked_sifs_with_backend(&root, local.clone());
    dfs.posix_mkdir_all("/services").expect("services dir");

    let stat = dfs
        .posix_write_file(
            "/services/async-repair.txt",
            b"commit locally and repair the remote replica later",
            DfsWriteOptions {
                policy: DfsReplicationPolicy::new(1, 2).expect("policy"),
                replica_candidates: vec![local.clone(), remote.clone()],
                wait_for_commit: true,
                foreground_replica_repair: false,
            },
        )
        .expect("non-foreground write");

    assert_eq!(
        stat.current_locations,
        vec![local],
        "the returned POSIX stat must not claim an async repair target is durable"
    );
    assert_eq!(
        dfs.operational_metrics().expect("metrics").repair_job_count,
        1,
        "the remote desired replica should remain queued for repair"
    );

    std::fs::remove_dir_all(root).ok();
}

struct StatelessPrimaryPeerTransport {
    primary_node_id: NodeId,
    content_root: PathBuf,
    metadata_root: PathBuf,
    control_plane: SharedDfsControlPlaneKvClient<InProcessKvStore>,
    trace: Arc<Mutex<Vec<String>>>,
}

impl StatelessPrimaryPeerTransport {
    async fn call_object_rpc_inner(
        &self,
        target_node_id: &NodeId,
        call: ObjectRpcSessionCall,
    ) -> Result<ObjectRpcSessionResult, DfsPeerTransportError> {
        if target_node_id != &self.primary_node_id {
            return Err(DfsPeerTransportError::new(format!(
                "unexpected stateless DFS target {target_node_id}"
            )));
        }
        let ObjectRpcSessionCall { request, body } = call;
        let command = if body.is_empty() {
            decode_dfs_message_rpc_request(&request)
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))?
        } else {
            let head = crate::body_rpc::decode_dfs_attachment_message_rpc_request(&request)
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
            let max_bytes = usize::try_from(head.attachment.total_size_bytes).map_err(|_| {
                DfsPeerTransportError::new(
                    "stateless DFS request attachment does not fit this platform address space",
                )
            })?;
            let bytes = body
                .collect_to_vec(max_bytes)
                .await
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
            crate::body_rpc::attach_dfs_message_request_attachment(head, bytes)
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))?
        };
        self.trace
            .lock()
            .expect("trace")
            .push(format!("in:{:?}", command.routed_message.message));
        let content = LocalContentStore::new(&self.content_root).expect("content");
        let metadata =
            LocalSobjMetadataBackend::new(DfsMetadataShardId::new("services"), &self.metadata_root)
                .expect("metadata");
        let result = process_dfs_message_command_for_test(
            self.primary_node_id.clone(),
            command,
            content,
            Box::new(metadata),
            Some(Box::new(self.control_plane.clone())),
        )
        .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
        for event in &result.events {
            self.trace
                .lock()
                .expect("trace")
                .push(format!("event:{event:?}"));
        }
        for message in &result.response.outbound_messages {
            self.trace
                .lock()
                .expect("trace")
                .push(format!("out:{:?}", message.message));
        }
        if let Some(attachment) = result.attachment {
            let max_bytes = usize::try_from(attachment.descriptor.total_size_bytes).map_err(|_| {
                DfsPeerTransportError::new(
                    "stateless DFS response attachment does not fit this platform address space",
                )
            })?;
            let bytes = attachment
                .source
                .collect_to_vec(max_bytes)
                .await
                .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
            let response = crate::body_rpc::encode_dfs_attachment_message_rpc_response(
                &request.route,
                result.response,
                attachment.descriptor,
            )
            .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
            return Ok(ObjectRpcSessionResult::new(
                response,
                ObjectRpcIncomingBody::bytes(bytes),
            ));
        }
        ObjectRpcResponse::encode_body(&request.route, &result.response)
            .map(ObjectRpcSessionResult::value)
            .map_err(|source| DfsPeerTransportError::new(source.to_string()))
    }
}

impl DfsPeerTransport for StatelessPrimaryPeerTransport {
    fn call_object_rpc(
        &self,
        target_node_id: &NodeId,
        call: ObjectRpcSessionCall,
        _options: DfsObjectRpcSendOptions,
    ) -> Result<ObjectRpcSessionResult, DfsPeerTransportError> {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|source| DfsPeerTransportError::new(source.to_string()))?;
        let result = runtime.block_on(self.call_object_rpc_inner(target_node_id, call));
        runtime.shutdown_timeout(Duration::from_millis(250));
        result
    }
}

impl AsyncDfsPeerTransport for StatelessPrimaryPeerTransport {
    fn call_object_rpc_async<'a>(
        &'a self,
        target_node_id: &'a NodeId,
        call: ObjectRpcSessionCall,
        _options: DfsObjectRpcSendOptions,
    ) -> DfsPeerTransportFuture<'a, Result<ObjectRpcSessionResult, DfsPeerTransportError>> {
        Box::pin(self.call_object_rpc_inner(target_node_id, call))
    }
}

#[test]
fn stateless_node_route_reader_write_commits_after_primary_fetch_receipt() {
    let root = temp_root("stateless-node_route-reader-write-primary-fetch");
    let writer =
        NodeId::from_legacy_named("node_stateless_node_route_writer").expect("writer node");
    let primary =
        NodeId::from_legacy_named("node_stateless_node_route_primary").expect("primary node");
    let object_id =
        DfsObjectId::from_legacy_named("obj_stateless_node_route_fetch").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_stateless_node_route_fetch_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_stateless_node_route_fetch_2").expect("version");
    let file_system = file_system(primary.clone());
    let control_plane = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    control_plane.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&file_system))
            .expect("filesystem config");
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: file_system.file_system_id.clone(),
                shard_id: "services".to_string(),
                primary_node_id: primary.clone(),
                replica_node_ids: vec![writer.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::PathPrefix {
                    prefix: "/services".to_string(),
                },
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("metadata shard");
    });
    let primary_content_root = root.join("primary-content");
    let primary_metadata_root = root.join("primary-metadata");
    let trace = Arc::new(Mutex::new(Vec::new()));
    {
        let mut primary_backend = LocalSobjMetadataBackend::new(
            DfsMetadataShardId::new("services"),
            &primary_metadata_root,
        )
        .expect("primary metadata");
        primary_backend
            .put_file_system(&file_system)
            .expect("primary filesystem");
        for object in distributed_sifs_bootstrap_objects(file_system.owner_node_id.clone()) {
            primary_backend
                .put_object(&object)
                .expect("primary SIFS bootstrap object");
        }
    }
    let peer = Arc::new(StatelessPrimaryPeerTransport {
        primary_node_id: primary.clone(),
        content_root: primary_content_root,
        metadata_root: primary_metadata_root,
        control_plane: control_plane.clone(),
        trace: Arc::clone(&trace),
    });
    let peer_transport: Arc<dyn DfsPeerTransport> = peer.clone();
    let async_peer_transport: Arc<dyn AsyncDfsPeerTransport> = peer;
    let transport = DfsNodeTransport::with_peer_transports_for_nodes(
        writer.clone(),
        vec![primary.clone()],
        Duration::from_millis(1),
        peer_transport,
        async_peer_transport,
    );
    let writer_content = LocalContentStore::new(root.join("writer-content")).expect("content");
    let mut dfs =
        NetworkedDfsService::new(transport, writer_content).with_control_plane(control_plane);
    dfs.add_file_system(file_system.clone())
        .expect("writer filesystem");
    let mut object = file_metadata(primary.clone());
    object.file_system_id = file_system.file_system_id.clone();
    object.object_id = object_id.clone();
    object.path = "/services/stateless-fetch.txt".to_string();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![writer.clone()];
    dfs.add_transient_object_metadata(object)
        .expect("stateless writer object view");

    let outcome = dfs
        .write_distributed_eventual_from_reader(
            DfsWriteRequest {
                file_system_id: file_system.file_system_id,
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: writer.clone(),
            },
            std::io::Cursor::new(b"stateless routed reader bytes".to_vec()),
            vec![writer.clone(), primary.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("routed reader write");
    let NetworkedDfsWriteOutcome::Pending { mut intent_id, .. } = outcome else {
        panic!("expected pending routed write, got {outcome:?}");
    };
    let mut committed = None;
    for _ in 0..20 {
        let _ = dfs.process_incoming().expect("process routed frames");
        let next = dfs.write_outcome(&intent_id).expect("write outcome");
        match next {
            NetworkedDfsWriteOutcome::Pending {
                intent_id: next_intent_id,
                ..
            } => {
                intent_id = next_intent_id;
                std::thread::sleep(Duration::from_millis(10));
            }
            outcome => {
                committed = Some(outcome);
                break;
            }
        }
    }
    let committed = committed.unwrap_or_else(|| {
        panic!(
            "routed write should commit; trace={:?}",
            trace.lock().expect("trace")
        )
    });

    assert!(
        matches!(
            &committed,
            NetworkedDfsWriteOutcome::Committed { version, .. } if version == &version_2
        ),
        "unexpected served routed write outcome: {committed:?}"
    );

    std::fs::remove_dir_all(root).ok();
}

fn seeded_durable_metadata_replica(
    root: PathBuf,
    shards: Vec<DfsMetadataShardConfig>,
    file_system: &DfsFileSystem,
    object: &DfsObjectMetadata,
) -> LocalShardedMetadataBackend {
    let mut backend =
        open_local_sharded_metadata_backend(root, shards).expect("metadata replica backend");
    backend
        .put_file_system(file_system)
        .expect("replicated filesystem metadata");
    let mut root_object = crate::namespace::directory_object(
        crate::namespace::SIFS_ROOT_PATH,
        file_system.owner_node_id.clone(),
    );
    root_object.file_system_id = file_system.file_system_id.clone();
    backend
        .put_object(&root_object)
        .expect("replicated root directory metadata");
    backend
        .put_object(object)
        .expect("replicated object metadata");
    backend
}

#[test]
fn posix_routed_strict_write_prefers_metadata_primary_replica() {
    let root = temp_root("posix-routed-strict-prefers-primary");
    let writer =
        NodeId::from_legacy_named("node_posix_routed_primary_pref_writer").expect("writer");
    let primary =
        NodeId::from_legacy_named("node_posix_routed_primary_pref_primary").expect("primary");
    let replica =
        NodeId::from_legacy_named("node_posix_routed_primary_pref_replica").expect("replica");
    let file_system = file_system(primary.clone());
    let control_plane = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    let shard = DfsMetadataShardConfig {
        file_system_id: file_system.file_system_id.clone(),
        shard_id: "root".to_string(),
        primary_node_id: primary.clone(),
        replica_node_ids: vec![writer.clone()],
        epoch: 1,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    control_plane.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&file_system))
            .expect("filesystem config");
        control.put_metadata_shard(&shard).expect("metadata shard");
    });

    let captured_desired = Arc::new(Mutex::new(None::<Vec<NodeId>>));
    let captured_desired_for_sender = Arc::clone(&captured_desired);
    let sender: DfsMessageSender = Arc::new(move |_target_node_id, command, _timeout| {
        if let DfsNetworkMessage::DistributedWriteRequest(command) = &command.routed_message.message
        {
            *captured_desired_for_sender.lock().expect("capture") =
                Some(command.desired_replica_nodes.clone());
        }
        Ok(DfsMessageResponse {
            request_id: command.request_id.clone(),
            outbound_messages: Vec::new(),
        })
    });
    let transport = DfsNodeTransport::with_connect_timeout(
        writer.clone(),
        vec![primary.clone()],
        Duration::from_millis(1),
        sender,
    );
    let mut object = file_metadata(primary.clone());
    object.file_system_id = file_system.file_system_id.clone();
    object.path = "/routed-primary-preferred.txt".to_string();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![writer.clone()];
    let writer_content = LocalContentStore::new(root.join("writer-content")).expect("content");
    let metadata = seeded_durable_metadata_replica(
        root.join("writer-metadata"),
        vec![shard],
        &file_system,
        &object,
    );
    let mut dfs = NetworkedDfsService::new(transport, writer_content)
        .with_control_plane(control_plane)
        .with_metadata_backend(metadata)
        .expect("attach writer metadata replica");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");

    dfs.posix_write_file(
        "/routed-primary-preferred.txt",
        b"strict routed POSIX write prefers primary",
        DfsWriteOptions {
            policy: DfsReplicationPolicy::new(2, 2).expect("policy"),
            replica_candidates: vec![writer.clone(), replica.clone()],
            wait_for_commit: false,
            foreground_replica_repair: true,
        },
    )
    .expect("pending routed write returns stat for existing object");

    assert_eq!(
        captured_desired.lock().expect("capture").clone(),
        Some(vec![writer, primary]),
        "routed strict POSIX write should choose the metadata primary as the second replica"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn posix_routed_materialized_write_sends_value() {
    let root = temp_root("posix-routed-value");
    let writer = NodeId::from_legacy_named("node_posix_routed_inline_writer").expect("writer");
    let primary = NodeId::from_legacy_named("node_posix_routed_inline_primary").expect("primary");
    let file_system = file_system(primary.clone());
    let control_plane = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    let shard = DfsMetadataShardConfig {
        file_system_id: file_system.file_system_id.clone(),
        shard_id: "root".to_string(),
        primary_node_id: primary.clone(),
        replica_node_ids: vec![writer.clone()],
        epoch: 1,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    control_plane.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&file_system))
            .expect("filesystem config");
        control.put_metadata_shard(&shard).expect("metadata shard");
    });

    let captured_command = Arc::new(Mutex::new(None::<DfsDistributedWriteCommand>));
    let captured_command_for_sender = Arc::clone(&captured_command);
    let sender: DfsMessageSender = Arc::new(move |_target_node_id, command, _timeout| {
        if let DfsNetworkMessage::DistributedWriteRequest(write_command) =
            &command.routed_message.message
        {
            *captured_command_for_sender.lock().expect("capture") = Some(write_command.clone());
        }
        Ok(DfsMessageResponse {
            request_id: command.request_id.clone(),
            outbound_messages: Vec::new(),
        })
    });
    let transport = DfsNodeTransport::with_connect_timeout(
        writer.clone(),
        vec![primary.clone()],
        Duration::from_millis(1),
        sender,
    );
    let mut object = file_metadata(primary.clone());
    object.file_system_id = file_system.file_system_id.clone();
    object.path = "/routed-value.txt".to_string();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![writer.clone()];
    let writer_content = LocalContentStore::new(root.join("writer-content")).expect("content");
    let metadata = seeded_durable_metadata_replica(
        root.join("writer-metadata"),
        vec![shard],
        &file_system,
        &object,
    );
    let mut dfs = NetworkedDfsService::new(transport, writer_content)
        .with_control_plane(control_plane)
        .with_metadata_backend(metadata)
        .expect("attach writer metadata replica");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");

    let bytes = b"materialized routed POSIX bytes".to_vec();
    let expected_hash = content_hash(&bytes);
    dfs.posix_write_file(
        "/routed-value.txt",
        &bytes,
        DfsWriteOptions {
            policy: DfsReplicationPolicy::new(2, 2).expect("policy"),
            replica_candidates: vec![writer.clone(), primary.clone()],
            wait_for_commit: false,
            foreground_replica_repair: true,
        },
    )
    .expect("pending routed write returns stat for existing object");

    let command = captured_command
        .lock()
        .expect("capture")
        .clone()
        .expect("captured routed write command");
    assert_eq!(command.bytes, bytes);
    assert_eq!(command.content_hash, None);
    assert_eq!(command.content_size_bytes, None);
    assert_eq!(command.desired_replica_nodes, vec![writer.clone(), primary]);
    assert_eq!(
        dfs.content
            .read_blob(&expected_hash)
            .expect("writer retained local blob"),
        b"materialized routed POSIX bytes"
    );

    std::fs::remove_dir_all(root).ok();
}

