#[test]
fn persisted_repair_attempts_prevent_duplicate_fetch_after_reopen() {
    let root = temp_root("persisted-repair-attempts-prevent-duplicate-fetch");
    let primary = NodeId::from_legacy_named("node_persisted_fetch_primary").expect("primary");
    let source = NodeId::from_legacy_named("node_persisted_fetch_source").expect("source");
    let target = NodeId::from_legacy_named("node_persisted_fetch_target").expect("target");
    let object_id = DfsObjectId::from_legacy_named("obj_persisted_fetch").expect("object");
    let version_1 = DfsVersion::from_legacy_named("version_persisted_fetch_1").expect("version");
    let version_2 = DfsVersion::from_legacy_named("version_persisted_fetch_2").expect("version");
    let content_hash = content_hash(b"persisted repair fetch body");
    let size_bytes = 2 * 1024 * 1024 + 17;
    let network = InProcessNetwork::new();
    let primary_transport = network.add_node(primary.clone());
    let mut source_transport = network.add_node(source.clone());
    let _target_transport = network.add_node(target.clone());
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata_backend =
        open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut dfs = NetworkedDfsService::new(primary_transport, content)
        .with_metadata_backend(metadata_backend)
        .expect("metadata backend");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut metadata = file_metadata(primary.clone());
    metadata.object_id = object_id.clone();
    metadata.path = "/services/persisted-fetch.bin".to_string();
    metadata.version = version_1.clone();
    metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    metadata.current_locations = Vec::new();
    metadata.content_hash = None;
    metadata.content_size_bytes = None;
    dfs.add_object_metadata(metadata).expect("object metadata");

    let intent = dfs
        .coordinator
        .create_intent(
            sifs_file_system_id(),
            object_id.clone(),
            Some(version_1.clone()),
            version_2.clone(),
            primary.clone(),
            vec![source.clone(), target.clone()],
            DfsReplicationPolicy::new(1, 2).expect("policy"),
        )
        .expect("intent");
    let intent_id = intent.intent_id.clone();
    dfs.coordinator
        .record_durable_receipt(&intent_id, source.clone())
        .expect("source receipt");
    dfs.coordinator
        .commit_intent(&intent_id)
        .expect("committed intent");
    let mut committed_metadata = file_metadata(primary.clone());
    committed_metadata.object_id = object_id.clone();
    committed_metadata.path = "/services/persisted-fetch.bin".to_string();
    committed_metadata.version = version_2.clone();
    committed_metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    committed_metadata.current_locations = vec![source.clone()];
    committed_metadata.content_hash = Some(content_hash.clone());
    committed_metadata.content_size_bytes = Some(size_bytes);
    dfs.add_object_metadata(committed_metadata)
        .expect("committed object metadata");
    assert_eq!(dfs.coordinator.repair_jobs().len(), 1);
    assert_eq!(
        dfs.coordinator.repair_jobs()[0].missing_replica_node_id,
        target
    );
    dfs.pending_writes.insert(
        intent_id.clone(),
        PendingNetworkedWrite::new(
            object_id.clone(),
            version_2,
            content_hash.clone(),
            size_bytes,
        ),
    );

    let scheduled = dfs
        .retry_pending_repairs_bounded(1)
        .expect("fetch-backed repair tick");
    assert!(
        scheduled.is_empty(),
        "fetch-backed repairs wait for the alternate source before scheduling target repair"
    );
    let fetches = drain_dfs_messages(&mut source_transport)
        .into_iter()
        .filter(|message| matches!(message, DfsNetworkMessage::FetchBlob(_)))
        .count();
    assert_eq!(fetches, 1, "first repair tick must request the blob once");
    let records = dfs.active_repair_attempt_records();
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].intent_id, intent_id);
    assert_eq!(records[0].missing_replica_node_id, target);
    assert!(records[0].in_flight);

    let pending = dfs
        .pending_writes
        .get_mut(&intent_id)
        .expect("pending write");
    pending.fetch_inflight_from.clear();
    pending.fetch_inflight_request_ids.clear();
    pending.fetch_inflight_started_ticks.clear();
    pending.repair_retries.clear();
    pending.repair_inflight_request_ids.clear();
    dfs.repair_attempt_records.clear();

    let duplicate = dfs
        .retry_pending_repairs_bounded_with_attempts(1, &records)
        .expect("restored fetch-backed repair tick");
    assert!(
        duplicate.is_empty(),
        "restored in-flight fetch attempt must honor durable backoff"
    );
    let duplicate_fetches = drain_dfs_messages(&mut source_transport)
        .into_iter()
        .filter(|message| matches!(message, DfsNetworkMessage::FetchBlob(_)))
        .count();
    assert_eq!(
        duplicate_fetches, 0,
        "restored maintenance must not duplicate the fetch request"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn retry_pending_repairs_skips_sender_that_lost_metadata_primary_authority() {
    let root = temp_root("retry-repair-skips-stale-primary");
    let owner = NodeId::from_legacy_named("node_repair_stale_primary_owner").expect("owner");
    let new_primary = NodeId::from_legacy_named("node_repair_stale_primary_new").expect("primary");
    let replica = NodeId::from_legacy_named("node_repair_stale_primary_replica").expect("replica");
    let object_id = DfsObjectId::from_legacy_named("obj_repair_stale_primary").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_repair_stale_primary_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_repair_stale_primary_2").expect("version");
    let file_system = file_system(owner.clone());
    let shared_kv = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&file_system))
            .expect("filesystem config");
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: file_system.file_system_id.clone(),
                shard_id: "services".to_string(),
                primary_node_id: owner.clone(),
                replica_node_ids: vec![new_primary.clone(), replica.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::PathPrefix {
                    prefix: "/services".to_string(),
                },
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("metadata shard");
    });
    let network = InProcessNetwork::new();
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("services"), root.join("metadata"))
            .expect("services metadata");
    let mut dfs = NetworkedDfsService::new(network.add_node(owner.clone()), content)
        .with_control_plane(shared_kv.clone())
        .with_metadata_backend(metadata)
        .expect("metadata backend");
    dfs.add_file_system(file_system.clone())
        .expect("filesystem");
    let mut object = file_metadata(owner.clone());
    object.file_system_id = file_system.file_system_id.clone();
    object.object_id = object_id.clone();
    object.path = "/services/stale-primary-repair.bin".to_string();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![owner.clone()];
    dfs.add_object_metadata(object).expect("object");

    let write = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: file_system.file_system_id.clone(),
                object_id: object_id.clone(),
                target_version: version_2,
                requesting_node_id: owner.clone(),
            },
            b"repair should not be sent from stale primary".to_vec(),
            vec![owner.clone(), replica.clone()],
            DfsReplicationPolicy::new(1, 2).expect("policy"),
        )
        .expect("committed write");
    let intent_id = match write {
        NetworkedDfsWriteOutcome::Committed {
            intent_id,
            repair_jobs,
            ..
        } => {
            assert_eq!(repair_jobs.len(), 1);
            assert_eq!(repair_jobs[0].missing_replica_node_id, replica);
            intent_id
        }
        other => panic!("expected committed write with pending repair, got {other:?}"),
    };

    let mut replica_mailbox = network.add_node(replica.clone());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: file_system.file_system_id.clone(),
                shard_id: "services".to_string(),
                primary_node_id: new_primary,
                replica_node_ids: vec![owner.clone(), replica.clone()],
                epoch: 2,
                assignment: DfsMetadataShardAssignment::PathPrefix {
                    prefix: "/services".to_string(),
                },
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("metadata primary move");
    });
    dfs.repair_retry_tick = 16;

    let scheduled = dfs.retry_pending_repairs().expect("retry repairs");

    assert!(
        scheduled.is_empty(),
        "stale metadata primary must not schedule remote repair frames"
    );
    assert!(
        drain_dfs_messages(&mut replica_mailbox).is_empty(),
        "stale metadata primary must not send repair frames after authority moves"
    );
    assert!(
        !dfs.pending_writes.contains_key(&intent_id),
        "stale committed repair state should be dropped after authority moves"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn retry_pending_repairs_suppresses_stale_content_target_after_object_advances() {
    let root = temp_root("retry-repair-suppresses-stale-content");
    let owner = NodeId::from_legacy_named("node_repair_stale_content_owner").expect("owner");
    let replica = NodeId::from_legacy_named("node_repair_stale_content_replica").expect("replica");
    let object_id = DfsObjectId::from_legacy_named("obj_repair_stale_content").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_repair_stale_content_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_repair_stale_content_2").expect("version");
    let version_3 =
        DfsVersion::from_legacy_named("version_repair_stale_content_3").expect("version");
    let network = InProcessNetwork::new();
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut dfs = NetworkedDfsService::new(network.add_node(owner.clone()), content)
        .with_metadata_backend(metadata)
        .expect("metadata backend");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut object = file_metadata(owner.clone());
    object.object_id = object_id.clone();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![owner.clone()];
    dfs.add_object_metadata(object).expect("object");

    let write = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2,
                requesting_node_id: owner.clone(),
            },
            b"stale repair target bytes".to_vec(),
            vec![owner.clone(), replica.clone()],
            DfsReplicationPolicy::new(1, 2).expect("policy"),
        )
        .expect("write should commit locally");
    let NetworkedDfsWriteOutcome::Committed {
        intent_id,
        repair_jobs,
        ..
    } = write
    else {
        panic!("expected committed write, got {write:?}");
    };
    assert_eq!(repair_jobs.len(), 1);
    assert_eq!(repair_jobs[0].missing_replica_node_id, replica);

    let mut replica_mailbox = network.add_node(replica.clone());
    let replacement_bytes = b"newer visible content should retire stale repair";
    let mut advanced = dfs
        .current_read_object_metadata(&object_id)
        .expect("current object");
    advanced.version = version_3;
    advanced.content_hash = Some(content_hash(replacement_bytes));
    advanced.content_size_bytes = Some(replacement_bytes.len() as u64);
    advanced.current_locations = vec![owner];
    dfs.add_object_metadata(advanced).expect("advanced object");

    dfs.repair_retry_tick = 32;
    let scheduled = dfs.retry_pending_repairs().expect("retry repairs");

    assert!(
        scheduled.is_empty(),
        "stale content repair must not schedule a remote frame"
    );
    assert!(
        drain_dfs_messages(&mut replica_mailbox).is_empty(),
        "stale content repair must not send repair or fetch frames"
    );
    assert!(
        !dfs.pending_writes.contains_key(&intent_id),
        "committed stale repair state should be dropped once the object content advances"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn retry_pending_repairs_keeps_same_content_after_metadata_only_advance() {
    let root = temp_root("retry-repair-keeps-same-content");
    let owner = NodeId::from_legacy_named("node_repair_same_content_owner").expect("owner");
    let replica = NodeId::from_legacy_named("node_repair_same_content_replica").expect("replica");
    let object_id = DfsObjectId::from_legacy_named("obj_repair_same_content").expect("object");
    let version_1 =
        DfsVersion::from_legacy_named("version_repair_same_content_1").expect("version");
    let version_2 =
        DfsVersion::from_legacy_named("version_repair_same_content_2").expect("version");
    let version_3 =
        DfsVersion::from_legacy_named("version_repair_same_content_3").expect("version");
    let network = InProcessNetwork::new();
    let content = LocalContentStore::new(root.join("content")).expect("content");
    let metadata = open_root_local_metadata_backend(root.join("metadata")).expect("metadata");
    let mut dfs = NetworkedDfsService::new(network.add_node(owner.clone()), content)
        .with_metadata_backend(metadata)
        .expect("metadata backend");
    dfs.bootstrap_distributed_sifs().expect("bootstrap sifs");
    let mut object = file_metadata(owner.clone());
    object.object_id = object_id.clone();
    object.version = version_1.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![owner.clone()];
    dfs.add_object_metadata(object).expect("object");

    let bytes = b"metadata-only version keeps this content";
    let expected_hash = content_hash(bytes);
    let write = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: owner.clone(),
            },
            bytes.to_vec(),
            vec![owner.clone(), replica.clone()],
            DfsReplicationPolicy::new(1, 2).expect("policy"),
        )
        .expect("write should commit locally");
    let NetworkedDfsWriteOutcome::Committed {
        intent_id,
        repair_jobs,
        ..
    } = write
    else {
        panic!("expected committed write, got {write:?}");
    };
    assert_eq!(repair_jobs.len(), 1);
    assert_eq!(repair_jobs[0].missing_replica_node_id, replica);

    let mut replica_mailbox = network.add_node(replica.clone());
    let mut advanced = dfs
        .current_read_object_metadata(&object_id)
        .expect("current object");
    advanced.version = version_3;
    advanced.content_hash = Some(expected_hash.clone());
    advanced.content_size_bytes = Some(bytes.len() as u64);
    advanced.current_locations = vec![owner];
    dfs.add_object_metadata(advanced).expect("advanced object");

    dfs.repair_retry_tick = 32;
    let scheduled = dfs.retry_pending_repairs().expect("retry repairs");

    assert_eq!(scheduled.len(), 1);
    assert!(
        dfs.pending_writes.contains_key(&intent_id),
        "same-content repair should remain pending until the replica receives it"
    );
    let messages = drain_dfs_messages(&mut replica_mailbox);
    assert!(matches!(
        messages.as_slice(),
        [DfsNetworkMessage::RepairReplica(command)]
            if command.intent_id == intent_id
                && command.object_id == object_id
                && command.version == version_2
                && command.content_hash == expected_hash
    ));
    std::fs::remove_dir_all(root).ok();
}

