#[test]
fn stat_derives_current_locations_from_matching_receipts_without_writing() {
    let root = temp_root("stat-derives-receipt-locations");
    let owner = NodeId::from_legacy_named("node_stat_receipt_owner").expect("owner");
    let replica = NodeId::from_legacy_named("node_stat_receipt_replica").expect("replica");
    let object_id = DfsObjectId::from_legacy_named("obj_stat_receipt").expect("object");
    let version = DfsVersion::from_legacy_named("version_2").expect("version");
    let content_hash = "blake3:stat-receipt-location";
    let mut dfs = networked_sifs_with_backend(&root, owner.clone());
    let mut metadata = file_metadata(owner.clone());
    metadata.object_id = object_id.clone();
    metadata.path = "/stat-receipt-location.bin".to_string();
    metadata.version = version.clone();
    metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    metadata.current_locations = vec![owner.clone()];
    metadata.content_hash = Some(content_hash.to_string());
    metadata.content_size_bytes = Some(17);
    dfs.put_visible_object_in_metadata_backend(&metadata)
        .expect("visible object");
    dfs.metadata_backend
        .as_mut()
        .expect("metadata backend")
        .put_receipt(&DfsReplicaReceiptRecord {
            receipt: DfsWriteReceipt {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                committed_version: version.clone(),
                owner_node_id: owner.clone(),
                event_id: EventId::generate(),
            },
            replica_node_id: replica.clone(),
            content_hash: Some(content_hash.to_string()),
            received_at: OffsetDateTime::now_utc(),
        })
        .expect("receipt");

    let stat = dfs
        .posix_stat_object(&object_id)
        .expect("stat")
        .expect("object");

    assert_eq!(
        stat.current_locations.iter().collect::<BTreeSet<_>>(),
        [&owner, &replica].into_iter().collect::<BTreeSet<_>>()
    );
    drop(dfs);

    let backend =
        open_root_local_metadata_backend(root.join("metadata")).expect("reopen metadata backend");
    assert_eq!(
        backend
            .get_object(&object_id)
            .expect("object")
            .expect("object")
            .current_locations,
        vec![owner.clone()],
        "stat must not persist read-side location reconciliation"
    );
    assert_eq!(
        backend
            .get_version(&object_id, &version)
            .expect("version")
            .expect("version")
            .locations,
        vec![owner],
        "stat must not rewrite the visible version record"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn stat_prefers_backend_tombstone_over_stale_memory_file() {
    let root = temp_root("stat-prefers-backend-tombstone");
    let owner = NodeId::from_legacy_named("node_stat_tombstone_owner").expect("owner");
    let object_id = DfsObjectId::from_legacy_named("obj_stat_tombstone").expect("object");
    let path = "/stat-tombstone.txt";
    let mut dfs = networked_sifs_with_backend(&root, owner.clone());
    let mut tombstone = file_metadata(owner.clone());
    tombstone.object_id = object_id.clone();
    tombstone.path = path.to_string();
    tombstone.kind = DfsObjectKind::Tombstone;
    tombstone.version = DfsVersion::from_legacy_named("version_2").expect("version");
    tombstone.content_hash = None;
    tombstone.content_size_bytes = None;
    tombstone.current_locations = vec![owner.clone()];
    dfs.put_visible_object_in_metadata_backend(&tombstone)
        .expect("backend tombstone");

    let mut stale_memory = tombstone.clone();
    stale_memory.kind = DfsObjectKind::File;
    stale_memory.version = DfsVersion::from_legacy_named("version_3").expect("version");
    stale_memory.content_hash = Some("blake3:stale-memory-file".to_string());
    stale_memory.content_size_bytes = Some(12);
    dfs.metadata
        .add_object(stale_memory)
        .expect("stale memory file");

    let error = dfs
        .posix_stat_distributed(path)
        .expect_err("backend tombstone must hide stale memory file");

    assert!(matches!(error, DfsPosixError::NotFound { .. }));
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn tombstone_tracking_ignores_stale_live_path_metadata() {
    let root = temp_root("tombstone-ignores-stale-live");
    let owner = NodeId::from_legacy_named("node_tombstone_stale_live").expect("owner");
    let path = "/tombstone-stale-live.txt";
    let mut dfs = networked_sifs_with_backend(&root, owner.clone());
    dfs.tombstones_by_metadata_path.clear();
    let stale_version = DfsVersion::new("00000000000000000000000001").expect("version");
    let tombstone_version = DfsVersion::new("00000000000000000000000002").expect("version");
    let fresh_version = DfsVersion::new("00000000000000000000000003").expect("version");

    let mut tombstone = file_metadata(owner.clone());
    tombstone.object_id =
        DfsObjectId::from_legacy_named("obj_tombstone_stale_live_delete").expect("object");
    tombstone.path = path.to_string();
    tombstone.kind = DfsObjectKind::Tombstone;
    tombstone.version = tombstone_version;
    dfs.track_metadata_tombstone(&tombstone);

    let key = (sifs_file_system_id(), metadata_path(path));
    assert!(
        dfs.tombstones_by_metadata_path.contains_key(&key),
        "newer tombstone should be tracked for the deleted path"
    );

    let mut stale_live = file_metadata(owner.clone());
    stale_live.object_id =
        DfsObjectId::from_legacy_named("obj_tombstone_stale_live_old").expect("object");
    stale_live.path = path.to_string();
    stale_live.version = stale_version;
    dfs.track_hydrated_metadata_tombstone(&stale_live);
    assert!(
        dfs.tombstones_by_metadata_path.contains_key(&key),
        "older live metadata must not clear a newer tombstone"
    );

    let mut fresh_live = stale_live;
    fresh_live.object_id =
        DfsObjectId::from_legacy_named("obj_tombstone_stale_live_fresh").expect("object");
    fresh_live.version = fresh_version;
    dfs.track_hydrated_metadata_tombstone(&fresh_live);
    assert!(
        !dfs.tombstones_by_metadata_path.contains_key(&key),
        "newer live metadata should clear the older tombstone"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
#[ignore = "slow page-boundary hydration regression; run with `cargo test -p sinomo-dfs hydrate_from_metadata_backend_walks_multiple_object_pages -- --ignored`"]
fn hydrate_from_metadata_backend_walks_multiple_object_pages() {
    let root = temp_root("hydrate-multiple-object-pages");
    let node_id = NodeId::from_legacy_named("node_hydrate_pages").expect("node");
    let mut dfs = networked_sifs_with_backend(&root, node_id.clone());
    let tail_index = DFS_METADATA_HYDRATE_OBJECT_PAGE_SIZE;
    let mut tail_object_id = None;
    for index in 0..=tail_index {
        let mut object = file_metadata(node_id.clone());
        object.object_id =
            DfsObjectId::from_legacy_named(format!("obj_hydrate_page_{index}")).expect("object");
        object.path = format!("/users/hydrate/page-{index:05}.txt");
        object.version = DfsVersion::from_legacy_named(format!("version_hydrate_page_{index}"))
            .expect("version");
        if index == tail_index {
            tail_object_id = Some(object.object_id.clone());
        }
        dfs.add_object_metadata(object).expect("metadata object");
    }

    let mut tombstone = file_metadata(node_id);
    tombstone.object_id =
        DfsObjectId::from_legacy_named("obj_hydrate_page_tombstone").expect("tombstone");
    tombstone.kind = DfsObjectKind::Tombstone;
    tombstone.path = "/users/hydrate/deleted.txt".to_string();
    dfs.add_object_metadata(tombstone.clone())
        .expect("tombstone metadata");

    dfs.metadata = DfsMetadataStore::new();
    dfs.tombstones_by_metadata_path.clear();
    dfs.hydrate_from_metadata_backend().expect("hydrate pages");

    let tail_object = dfs
        .current_read_object_metadata(&tail_object_id.expect("tail object"))
        .expect("tail object loaded");
    assert_eq!(
        tail_object.path,
        format!("/users/hydrate/page-{tail_index:05}.txt")
    );
    assert!(
        dfs.tombstones_by_metadata_path
            .contains_key(&(sifs_file_system_id(), metadata_path(&tombstone.path))),
        "paged hydration must restore tombstone tracking"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn hydrated_tombstone_tracking_is_incremental_and_live_path_aware() {
    let root = temp_root("hydrate-incremental-tombstones");
    let node_id = NodeId::from_legacy_named("node_hydrate_tombstones").expect("node");
    let mut dfs = networked_sifs_with_backend(&root, node_id.clone());
    dfs.metadata = DfsMetadataStore::new();
    dfs.metadata.add_file_system(file_system(node_id.clone()));
    dfs.tombstones_by_metadata_path.clear();

    let mut live_first = file_metadata(node_id.clone());
    live_first.object_id =
        DfsObjectId::from_legacy_named("obj_hydrate_live_first").expect("object");
    live_first.path = "/users/hydrate/live-first.txt".to_string();
    dfs.metadata
        .add_object(live_first.clone())
        .expect("live object");

    let mut late_tombstone = file_metadata(node_id.clone());
    late_tombstone.object_id =
        DfsObjectId::from_legacy_named("obj_hydrate_late_tombstone").expect("object");
    late_tombstone.kind = DfsObjectKind::Tombstone;
    late_tombstone.path = live_first.path.clone();
    dfs.track_hydrated_metadata_tombstone(&late_tombstone);
    assert!(
        !dfs.tombstones_by_metadata_path
            .contains_key(&(sifs_file_system_id(), metadata_path(&late_tombstone.path))),
        "hydration must not retain a tombstone for a path already owned by a live object"
    );

    let mut early_tombstone = file_metadata(node_id.clone());
    early_tombstone.object_id =
        DfsObjectId::from_legacy_named("obj_hydrate_early_tombstone").expect("object");
    early_tombstone.kind = DfsObjectKind::Tombstone;
    early_tombstone.path = "/users/hydrate/live-after-tombstone.txt".to_string();
    dfs.track_hydrated_metadata_tombstone(&early_tombstone);
    assert!(
        dfs.tombstones_by_metadata_path
            .contains_key(&(sifs_file_system_id(), metadata_path(&early_tombstone.path))),
        "a tombstone should be tracked until hydration sees a live object for the path"
    );

    let mut live_later = file_metadata(node_id);
    live_later.object_id =
        DfsObjectId::from_legacy_named("obj_hydrate_live_later").expect("object");
    live_later.path = early_tombstone.path.clone();
    dfs.track_hydrated_metadata_tombstone(&live_later);
    assert!(
        !dfs.tombstones_by_metadata_path
            .contains_key(&(sifs_file_system_id(), metadata_path(&early_tombstone.path))),
        "a later live object should clear a previously tracked hydrated tombstone"
    );

    std::fs::remove_dir_all(root).ok();
}

#[test]
fn hydrate_from_metadata_backend_walks_multiple_conflict_pages() {
    let root = temp_root("hydrate-multiple-conflict-pages");
    let node_id = NodeId::from_legacy_named("node_hydrate_conflict_pages").expect("node");
    let mut dfs = networked_sifs_with_backend(&root, node_id.clone());
    let object_id = DfsObjectId::from_legacy_named("obj_hydrate_conflict_pages").expect("object");
    let mut object = file_metadata(node_id.clone());
    object.object_id = object_id.clone();
    object.path = "/users/hydrate/conflicted.txt".to_string();
    object.version =
        DfsVersion::from_legacy_named("version_hydrate_conflict_remote").expect("remote version");
    dfs.add_object_metadata(object.clone())
        .expect("metadata object");

    let conflict_count = DFS_CONFLICT_SCAN_PAGE_SIZE + 1;
    for index in 0..conflict_count {
        let conflict = DfsConflictRecord {
            conflict_id: format!("conflict_hydrate_page_{index:04}"),
            file_system_id: object.file_system_id.clone(),
            object_id: object_id.clone(),
            path: object.path.clone(),
            base_version: Some(
                DfsVersion::from_legacy_named("version_hydrate_conflict_base")
                    .expect("base version"),
            ),
            local_version: DfsVersion::from_legacy_named(format!(
                "version_hydrate_conflict_local_{index}"
            ))
            .expect("local version"),
            remote_version: object.version.clone(),
            detected_by_node_id: node_id.clone(),
            reason: "restart hydration must page conflict records".to_string(),
            local_content_hash: Some(format!("blake3:local-hydrate-conflict-{index}")),
            remote_content_hash: object.content_hash.clone(),
            created_by_intent_id: None,
            strategy: Some("branch".to_string()),
            status: DfsConflictStatus::Open,
            detected_at: OffsetDateTime::UNIX_EPOCH,
        };
        dfs.put_conflict_record(&conflict).expect("conflict record");
    }

    dfs.metadata = DfsMetadataStore::new();
    dfs.hydrate_from_metadata_backend()
        .expect("hydrate conflict pages");

    let loaded_conflicts = dfs
        .conflicts_for_object(&object_id)
        .expect("loaded conflicts");
    assert_eq!(
        loaded_conflicts.len(),
        conflict_count,
        "hydration must walk every conflict page for an object"
    );
    assert_eq!(
        loaded_conflicts.last().expect("tail conflict").conflict_id,
        format!("conflict_hydrate_page_{:04}", conflict_count - 1)
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn hydrate_from_metadata_backend_does_not_resurrect_aborted_pending_write() {
    let root = temp_root("hydrate-skips-aborted-pending-write");
    let owner = NodeId::from_legacy_named("node_hydrate_abort_owner").expect("node");
    let replica = NodeId::from_legacy_named("node_hydrate_abort_replica").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_hydrate_abort").expect("object");
    let version_1 = DfsVersion::from_legacy_named("version_1").expect("version");
    let version_2 = DfsVersion::from_legacy_named("version_2").expect("version");
    let mut dfs = networked_sifs_with_backend(&root, owner.clone());
    let mut metadata = file_metadata(owner.clone());
    metadata.object_id = object_id.clone();
    metadata.version = version_1.clone();
    metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    dfs.add_object_metadata(metadata).expect("object");

    let write = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: owner.clone(),
            },
            b"aborted pending bytes".to_vec(),
            vec![dfs.node_id().clone(), replica.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("pending write");
    let intent_id = match write {
        NetworkedDfsWriteOutcome::Pending { intent_id, .. } => intent_id,
        other => panic!("expected pending write, got {other:?}"),
    };
    dfs.abort_pending_write(&intent_id).expect("abort");
    assert!(
        !dfs.pending_writes.contains_key(&intent_id),
        "abort should remove in-memory pending write"
    );

    dfs.hydrate_from_metadata_backend().expect("rehydrate");

    let restored_aborted_intent = dfs
        .metadata_backend()
        .expect("metadata backend")
        .get_intent(&object_id, &intent_id)
        .expect("aborted intent lookup")
        .expect("aborted intent remains durable");
    assert_eq!(
        restored_aborted_intent.status,
        DfsWriteIntentStatus::Aborted
    );
    assert!(
        dfs.coordinator().intent(&intent_id).is_none(),
        "closed aborted intents should advance restored ID state without occupying coordinator memory"
    );
    assert_eq!(
        dfs.metadata()
            .object(&object_id)
            .expect("visible object")
            .version,
        version_1
    );
    assert!(
        !dfs.pending_writes.contains_key(&intent_id),
        "rehydration must not resurrect pending state for aborted writes"
    );
    let next_write = dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2,
                requesting_node_id: owner,
            },
            b"aborted pending bytes".to_vec(),
            vec![dfs.node_id().clone(), replica],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("retry pending write");
    let next_intent_id = match next_write {
        NetworkedDfsWriteOutcome::Pending { intent_id, .. } => intent_id,
        other => panic!("expected retry pending write, got {other:?}"),
    };
    assert_ne!(
        next_intent_id, intent_id,
        "hydration must observe closed intent ids so new writes do not reuse them"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn hydrate_from_metadata_backend_rejects_competing_pending_intent_without_conflict() {
    let root = temp_root("hydrate-competing-pending-intent-reject");
    let owner = NodeId::from_legacy_named("node_hydrate_conflict_owner").expect("node");
    let replica = NodeId::from_legacy_named("node_hydrate_conflict_replica").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_hydrate_conflict").expect("object");
    let version_1 = DfsVersion::from_legacy_named("version_1").expect("version");
    let version_2 = DfsVersion::from_legacy_named("version_2").expect("version");
    let version_3 = DfsVersion::from_legacy_named("version_3").expect("version");
    let second_bytes = b"recovered competing pending write";
    let network = InProcessNetwork::new();
    let metadata_root = root.join("metadata");
    let content_root = root.join("owner-content");
    let owner_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &metadata_root)
            .expect("owner backend");
    let mut owner_dfs = NetworkedDfsService::new(
        network.add_node(owner.clone()),
        LocalContentStore::new(&content_root).expect("owner content"),
    )
    .with_metadata_backend(owner_backend)
    .expect("metadata backend");
    let mut metadata = file_metadata(owner.clone());
    metadata.object_id = object_id.clone();
    metadata.version = version_1.clone();
    metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    owner_dfs
        .add_file_system(file_system(owner.clone()))
        .expect("owner fs");
    owner_dfs
        .add_object_metadata(metadata)
        .expect("owner object");

    let first = owner_dfs
        .write_distributed_eventual(
            DfsWriteRequest {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                target_version: version_2.clone(),
                requesting_node_id: owner.clone(),
            },
            b"first pending write".to_vec(),
            vec![owner.clone(), replica.clone()],
            DfsReplicationPolicy::new(2, 2).expect("policy"),
        )
        .expect("first pending write");
    let first_intent_id = match first {
        NetworkedDfsWriteOutcome::Pending { intent_id, .. } => intent_id,
        other => panic!("expected pending write, got {other:?}"),
    };
    let second_hash = owner_dfs
        .content()
        .put_object_version(object_id.as_str(), version_3.as_str(), second_bytes)
        .expect("second content")
        .content_hash;
    owner_dfs
        .metadata_backend
        .as_mut()
        .expect("backend")
        .put_intent(&DfsWriteIntentRecord {
            intent_id: format!("dfs_intent_{}_99", owner.as_str()),
            file_system_id: sifs_file_system_id(),
            object_id: object_id.clone(),
            base_version: Some(version_1.clone()),
            target_version: version_3.clone(),
            coordinator_node_id: owner.clone(),
            owner_epoch: 0,
            desired_replica_node_ids: vec![owner.clone(), replica],
            policy: DfsReplicationPolicy::new(2, 2).expect("policy"),
            status: DfsWriteIntentStatus::ReceiptsPending,
            content_hash: Some(second_hash.clone()),
            object_metadata: None,
            touch_parent_on_create: false,
            create_predecessor_object_id: None,
            created_at: OffsetDateTime::now_utc() + time::Duration::seconds(1),
            updated_at: Some(OffsetDateTime::now_utc() + time::Duration::seconds(1)),
        })
        .expect("competing persisted intent");
    drop(owner_dfs);

    let recovered_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &metadata_root)
            .expect("recovered backend");
    let recovered_owner = NetworkedDfsService::new(
        network.add_node(owner.clone()),
        LocalContentStore::new(content_root).expect("recovered content"),
    )
    .with_metadata_backend(recovered_backend)
    .expect("competing pending intent should hydrate as rejected");

    assert!(
        recovered_owner
            .pending_writes
            .contains_key(&first_intent_id),
        "the earliest pending intent should remain repairable"
    );
    assert_eq!(
        recovered_owner
            .metadata()
            .object(&object_id)
            .expect("visible object")
            .version,
        version_1,
        "rejected recovered intent must not publish a visible version"
    );
    let conflicts = recovered_owner
        .conflicts_for_object(&object_id)
        .expect("conflicts");
    assert!(
        conflicts.is_empty(),
        "normal hydrate rejection must not create DFS conflicts"
    );
    let recovered_intent = recovered_owner
        .metadata_backend()
        .expect("backend")
        .get_intent(&object_id, &format!("dfs_intent_{}_99", owner.as_str()))
        .expect("intent")
        .expect("intent");
    assert_eq!(recovered_intent.status, DfsWriteIntentStatus::Rejected);
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn hydrate_from_metadata_backend_repairs_visible_target_pending_intent() {
    let root = temp_root("hydrate-repairs-visible-target-pending");
    let owner = NodeId::from_legacy_named("node_hydrate_visible_owner").expect("node");
    let replica = NodeId::from_legacy_named("node_hydrate_visible_replica").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_hydrate_visible").expect("object");
    let version_1 = DfsVersion::from_legacy_named("version_1").expect("version");
    let version_2 = DfsVersion::from_legacy_named("version_2").expect("version");
    let bytes = b"visible target already committed";
    let network = InProcessNetwork::new();
    let metadata_root = root.join("metadata");
    let content_root = root.join("owner-content");
    let owner_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &metadata_root)
            .expect("owner backend");
    let mut owner_dfs = NetworkedDfsService::new(
        network.add_node(owner.clone()),
        LocalContentStore::new(&content_root).expect("owner content"),
    )
    .with_metadata_backend(owner_backend)
    .expect("metadata backend");
    let manifest = owner_dfs
        .content()
        .put_object_version(object_id.as_str(), version_2.as_str(), bytes)
        .expect("content manifest");
    let mut metadata = file_metadata(owner.clone());
    metadata.object_id = object_id.clone();
    metadata.version = version_2.clone();
    metadata.policy = DfsObjectPolicy::ReplicatedEventual;
    metadata.content_hash = Some(manifest.content_hash.clone());
    metadata.content_size_bytes = Some(manifest.size_bytes);
    metadata.current_locations = vec![owner.clone(), replica.clone()];
    owner_dfs
        .add_file_system(file_system(owner.clone()))
        .expect("owner fs");
    owner_dfs
        .add_object_metadata(metadata)
        .expect("visible object");
    let intent_id = format!("dfs_intent_{}_42", owner.as_str());
    owner_dfs
        .metadata_backend
        .as_mut()
        .expect("metadata backend")
        .put_intent(&DfsWriteIntentRecord {
            intent_id: intent_id.clone(),
            file_system_id: sifs_file_system_id(),
            object_id: object_id.clone(),
            base_version: Some(version_1),
            target_version: version_2.clone(),
            coordinator_node_id: owner.clone(),
            owner_epoch: 0,
            desired_replica_node_ids: vec![owner.clone(), replica.clone()],
            policy: DfsReplicationPolicy::new(2, 2).expect("policy"),
            status: DfsWriteIntentStatus::ReceiptsPending,
            content_hash: Some(manifest.content_hash.clone()),
            object_metadata: None,
            touch_parent_on_create: false,
            create_predecessor_object_id: None,
            created_at: OffsetDateTime::now_utc(),
            updated_at: Some(OffsetDateTime::now_utc()),
        })
        .expect("stale pending intent");
    owner_dfs
        .metadata_backend
        .as_mut()
        .expect("metadata backend")
        .put_receipt(&DfsReplicaReceiptRecord {
            receipt: DfsWriteReceipt {
                file_system_id: sifs_file_system_id(),
                object_id: object_id.clone(),
                committed_version: version_2.clone(),
                owner_node_id: owner.clone(),
                event_id: EventId::generate(),
            },
            replica_node_id: owner.clone(),
            content_hash: Some(manifest.content_hash.clone()),
            received_at: OffsetDateTime::now_utc(),
        })
        .expect("local receipt");
    drop(owner_dfs);

    let recovered_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &metadata_root)
            .expect("recovered backend");
    let recovered_owner = NetworkedDfsService::new(
        network.add_node(owner.clone()),
        LocalContentStore::new(content_root).expect("recovered content"),
    )
    .with_metadata_backend(recovered_backend)
    .expect("visible target stale pending intent should hydrate");

    let recovered_intent = recovered_owner
        .metadata_backend()
        .expect("backend")
        .get_intent(&object_id, &intent_id)
        .expect("intent")
        .expect("intent");
    assert_eq!(recovered_intent.status, DfsWriteIntentStatus::Committed);
    assert!(
        recovered_owner.pending_writes.contains_key(&intent_id),
        "outstanding repair work should retain pending write state after hydration"
    );
    assert_eq!(
        recovered_owner.coordinator().repair_jobs().len(),
        1,
        "unverified replica locations should remain repair work after hydration"
    );
    let recovered_receipts = recovered_owner
        .metadata_backend()
        .expect("backend")
        .receipts_for_version(&object_id, &version_2)
        .expect("receipts");
    assert!(
        recovered_receipts
            .iter()
            .any(|receipt| receipt.replica_node_id == owner),
        "hydration should restore verified backend receipts"
    );
    assert!(
        !recovered_receipts
            .iter()
            .any(|receipt| receipt.replica_node_id == replica),
        "hydration must not synthesize receipts for unverified remote replicas"
    );
    std::fs::remove_dir_all(root).ok();
}

struct DurableCommitPromotionFixture {
    owner: NodeId,
    replica: NodeId,
    object_id: DfsObjectId,
    target_version: DfsVersion,
    intent_id: String,
    content_hash: String,
    metadata_root: PathBuf,
    content_root: PathBuf,
}

fn seed_durable_commit_promotion_fixture(
    root: &Path,
    suffix: &str,
) -> DurableCommitPromotionFixture {
    let owner =
        NodeId::from_legacy_named(format!("node_recovery_hydrate_owner_{suffix}")).expect("owner");
    let replica = NodeId::from_legacy_named(format!("node_recovery_hydrate_replica_{suffix}"))
        .expect("replica");
    let object_id =
        DfsObjectId::from_legacy_named(format!("obj_recovery_hydrate_{suffix}")).expect("object");
    let base_version =
        DfsVersion::from_legacy_named(format!("version_recovery_hydrate_base_{suffix}"))
            .expect("base version");
    let target_version =
        DfsVersion::from_legacy_named(format!("version_recovery_hydrate_target_{suffix}"))
            .expect("target version");
    let metadata_root = root.join("metadata");
    let content_root = root.join("content");
    let content = LocalContentStore::new(&content_root).expect("content store");
    let manifest = content
        .put_object_version(
            object_id.as_str(),
            target_version.as_str(),
            format!("durable promotion recovery {suffix}").as_bytes(),
        )
        .expect("content manifest");
    let file_system = file_system(owner.clone());
    let mut object = file_metadata(owner.clone());
    object.object_id = object_id.clone();
    object.path = format!("/services/recovery-hydrate-{suffix}.txt");
    object.version = target_version.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.content_hash = Some(manifest.content_hash.clone());
    object.content_size_bytes = Some(manifest.size_bytes);
    object.current_locations = vec![owner.clone(), replica.clone()];
    let intent_id = format!("dfs_intent_recovery_hydrate_{suffix}");
    let now = OffsetDateTime::now_utc();
    let intent = DfsWriteIntentRecord {
        intent_id,
        file_system_id: file_system.file_system_id.clone(),
        object_id: object_id.clone(),
        base_version: Some(base_version),
        target_version: target_version.clone(),
        coordinator_node_id: owner.clone(),
        owner_epoch: 0,
        desired_replica_node_ids: vec![owner.clone(), replica.clone()],
        policy: DfsReplicationPolicy::new(2, 2).expect("replication policy"),
        status: DfsWriteIntentStatus::Committed,
        content_hash: Some(manifest.content_hash.clone()),
        object_metadata: None,
        touch_parent_on_create: false,
        create_predecessor_object_id: None,
        created_at: now,
        updated_at: Some(now),
    };
    let receipts =
        [owner.clone(), replica.clone()].map(|replica_node_id| DfsReplicaReceiptRecord {
            receipt: DfsWriteReceipt {
                file_system_id: file_system.file_system_id.clone(),
                object_id: object_id.clone(),
                committed_version: target_version.clone(),
                owner_node_id: owner.clone(),
                event_id: EventId::generate(),
            },
            replica_node_id,
            content_hash: Some(manifest.content_hash.clone()),
            received_at: now,
        });
    let mut backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &metadata_root)
            .expect("metadata backend");
    backend.put_file_system(&file_system).expect("filesystem");
    backend
        .put_object_and_version(
            &object,
            &object_version_record(&object, Some(manifest.size_bytes)),
        )
        .expect("object and version");
    backend.put_intent(&intent).expect("committed intent");
    for receipt in receipts {
        backend.put_receipt(&receipt).expect("durable receipt");
    }
    DurableCommitPromotionFixture {
        owner,
        replica,
        object_id,
        target_version,
        intent_id: intent.intent_id,
        content_hash: manifest.content_hash,
        metadata_root,
        content_root,
    }
}

#[test]
fn missing_local_commit_content_transitions_stale_receipt_into_fetch_repair() {
    let root = temp_root("missing-commit-content-fetch-repair");
    let fixture = seed_durable_commit_promotion_fixture(&root, "missing-content-fetch");
    let network = InProcessNetwork::new();
    let mut owner_transport = network.add_node(fixture.owner.clone());
    let target_content_root = root.join("target-content");
    let target_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("target metadata backend");
    let mut target = NetworkedDfsService::new(
        network.add_node(fixture.replica.clone()),
        LocalContentStore::new(&target_content_root).expect("empty target content"),
    )
    .with_metadata_backend(target_backend)
    .expect("target metadata hydration");
    assert!(target.coordinator().repair_jobs().is_empty());
    assert!(
        target
            .content()
            .read_manifest(fixture.object_id.as_str(), fixture.target_version.as_str())
            .is_err(),
        "the stale target receipt must begin without local content"
    );
    let object_metadata = target
        .metadata()
        .object(&fixture.object_id)
        .cloned()
        .expect("committed object metadata");

    let event = target
        .handle_commit_version(
            fixture.owner.clone(),
            DfsCommitVersionCommand {
                request_id: "commit_missing_content_fetch_repair".to_string(),
                intent_id: fixture.intent_id.clone(),
                file_system_id: object_metadata.file_system_id.clone(),
                object_id: fixture.object_id.clone(),
                expected_base_version: None,
                version: fixture.target_version.clone(),
                content_hash: fixture.content_hash.clone(),
                object_metadata: Some(object_metadata),
                authority_shard: None,
            },
        )
        .expect("missing commit content response");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RepairRejected { ref reason, .. }
            if dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    let response = drain_dfs_messages(&mut owner_transport)
        .into_iter()
        .find_map(|message| match message {
            DfsNetworkMessage::CommitVersionResponse(response) => Some(response),
            _ => None,
        })
        .expect("commit response");
    assert!(matches!(
        response.result,
        DfsBlobTransferResult::Rejected { ref reason }
            if dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));

    let backend = target.metadata_backend().expect("target backend");
    assert_eq!(
        backend
            .get_intent(&fixture.object_id, &fixture.intent_id)
            .expect("committed intent")
            .expect("committed intent")
            .status,
        DfsWriteIntentStatus::Committed,
        "repair transition must preserve the committed intent"
    );
    assert!(
        !backend
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("receipts after transition")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "the stale target receipt must be durably removed"
    );
    assert!(
        !backend
            .get_object(&fixture.object_id)
            .expect("object after transition")
            .expect("object after transition")
            .current_locations
            .contains(&fixture.replica),
        "the stale target location must be durably removed"
    );
    drop(target);

    let target_backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("reopened target metadata backend");
    let mut target = NetworkedDfsService::new(
        network.add_node(fixture.replica.clone()),
        LocalContentStore::new(&target_content_root).expect("reopened target content"),
    )
    .with_metadata_backend(target_backend)
    .expect("reopened target hydration");
    assert_eq!(target.coordinator().repair_jobs().len(), 1);
    assert_eq!(
        target.coordinator().repair_jobs()[0].missing_replica_node_id,
        fixture.replica
    );
    let mut owner = NetworkedDfsService::new(
        owner_transport,
        LocalContentStore::new(&fixture.content_root).expect("owner source content"),
    );

    let scheduled = target
        .retry_pending_repairs_bounded(1)
        .expect("request exact content from durable source");
    assert!(
        scheduled.is_empty(),
        "self-repair waits for the exact source fetch before committing"
    );
    owner.process_incoming().expect("serve exact source fetch");
    target
        .process_incoming()
        .expect("accept fetched exact content");

    assert!(target.coordinator().repair_jobs().is_empty());
    assert!(
        target
            .metadata_backend()
            .expect("repaired backend")
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("repaired receipts")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "fetch completion must restore the target durability receipt"
    );
    let manifest = target
        .content()
        .read_manifest(fixture.object_id.as_str(), fixture.target_version.as_str())
        .expect("repaired target manifest");
    assert_eq!(manifest.content_hash, fixture.content_hash);
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn missing_local_commit_content_prunes_receipt_when_locations_are_already_absent() {
    let root = temp_root("missing-commit-content-stale-receipt-only");
    let fixture = seed_durable_commit_promotion_fixture(&root, "stale-receipt-only");
    let mut backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("metadata backend");
    let mut object = backend
        .get_object(&fixture.object_id)
        .expect("object")
        .expect("object");
    object
        .current_locations
        .retain(|node_id| node_id != &fixture.replica);
    let mut version = backend
        .get_version(&fixture.object_id, &fixture.target_version)
        .expect("version")
        .expect("version");
    version
        .locations
        .retain(|node_id| node_id != &fixture.replica);
    backend
        .put_object_and_version(&object, &version)
        .expect("pre-pruned locations");
    assert!(
        backend
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("stale receipts")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "the fixture must retain only the stale durable receipt"
    );

    let network = InProcessNetwork::new();
    let _owner_transport = network.add_node(fixture.owner.clone());
    let mut target = NetworkedDfsService::new(
        network.add_node(fixture.replica.clone()),
        LocalContentStore::new(root.join("target-content")).expect("empty target content"),
    )
    .with_metadata_backend(backend)
    .expect("target metadata hydration");
    let object_metadata = target
        .metadata()
        .object(&fixture.object_id)
        .cloned()
        .expect("committed object metadata");

    let event = target
        .handle_commit_version(
            fixture.owner,
            DfsCommitVersionCommand {
                request_id: "commit_missing_content_stale_receipt_only".to_string(),
                intent_id: fixture.intent_id.clone(),
                file_system_id: object_metadata.file_system_id.clone(),
                object_id: fixture.object_id.clone(),
                expected_base_version: None,
                version: fixture.target_version.clone(),
                content_hash: fixture.content_hash.clone(),
                object_metadata: Some(object_metadata),
                authority_shard: None,
            },
        )
        .expect("repair-pending response");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RepairRejected { ref reason, .. }
            if dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    assert!(
        !target
            .metadata_backend()
            .expect("target backend")
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("receipts after transition")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "terminal repair-pending requires the stale receipt to be durably absent"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn missing_local_commit_content_without_source_remains_pending_with_backoff() {
    let root = temp_root("missing-commit-content-no-source");
    let fixture = seed_durable_commit_promotion_fixture(&root, "missing-content-no-source");
    let target_content_root = root.join("target-content");
    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("target metadata backend");
    let mut target = NetworkedDfsService::new(
        ReceiveOnlyTransport::new(fixture.replica.clone()),
        LocalContentStore::new(&target_content_root).expect("empty target content"),
    )
    .with_metadata_backend(backend)
    .expect("target metadata hydration");
    let object_metadata = target
        .metadata()
        .object(&fixture.object_id)
        .cloned()
        .expect("committed object metadata");

    let _ = target.handle_commit_version(
        fixture.owner,
        DfsCommitVersionCommand {
            request_id: "commit_missing_content_no_source".to_string(),
            intent_id: fixture.intent_id.clone(),
            file_system_id: object_metadata.file_system_id.clone(),
            object_id: fixture.object_id.clone(),
            expected_base_version: None,
            version: fixture.target_version.clone(),
            content_hash: fixture.content_hash.clone(),
            object_metadata: Some(object_metadata),
            authority_shard: None,
        },
    );
    drop(target);

    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("reopened target metadata backend");
    let mut target = NetworkedDfsService::new(
        ReceiveOnlyTransport::new(fixture.replica.clone()),
        LocalContentStore::new(&target_content_root).expect("reopened target content"),
    )
    .with_metadata_backend(backend)
    .expect("reopened target hydration");
    assert_eq!(target.coordinator().repair_jobs().len(), 1);

    assert!(
        target
            .retry_pending_repairs_bounded(1)
            .expect("bounded missing-source repair")
            .is_empty()
    );
    assert_eq!(target.coordinator().repair_jobs().len(), 1);
    assert!(target.pending_writes.contains_key(&fixture.intent_id));
    let attempts = target.active_repair_attempt_records();
    assert_eq!(attempts.len(), 1);
    assert!(!attempts[0].in_flight);
    assert!(attempts[0].next_retry_unix_nanos > attempts[0].last_attempt_unix_nanos);
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn missing_local_commit_content_on_non_authority_keeps_receipt_retryable() {
    let root = temp_root("missing-commit-content-non-authority");
    let fixture = seed_durable_commit_promotion_fixture(&root, "missing-content-non-authority");
    let shared_kv = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig {
                file_system_id: sifs_file_system_id(),
                display_name: "SIFS".to_string(),
                owner_node_id: fixture.owner.clone(),
                subtree_policies: Vec::new(),
            })
            .expect("filesystem config");
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: sifs_file_system_id(),
                shard_id: "services".to_string(),
                primary_node_id: fixture.owner.clone(),
                replica_node_ids: vec![fixture.replica.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::PathPrefix {
                    prefix: "/services".to_string(),
                },
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("services shard");
    });
    let network = InProcessNetwork::new();
    let mut owner_transport = network.add_node(fixture.owner.clone());
    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("target metadata backend");
    let mut target = NetworkedDfsService::new(
        network.add_node(fixture.replica.clone()),
        LocalContentStore::new(root.join("target-content")).expect("empty target content"),
    )
    .with_control_plane(shared_kv)
    .with_metadata_backend(backend)
    .expect("target metadata hydration");
    let object_metadata = target
        .metadata()
        .object(&fixture.object_id)
        .cloned()
        .expect("committed object metadata");

    let event = target
        .handle_commit_version(
            fixture.owner,
            DfsCommitVersionCommand {
                request_id: "commit_missing_content_non_authority".to_string(),
                intent_id: fixture.intent_id.clone(),
                file_system_id: object_metadata.file_system_id.clone(),
                object_id: fixture.object_id.clone(),
                expected_base_version: None,
                version: fixture.target_version.clone(),
                content_hash: fixture.content_hash.clone(),
                object_metadata: Some(object_metadata),
                authority_shard: None,
            },
        )
        .expect("retryable missing-content response");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RepairRejected { ref reason, .. }
            if !dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    let response = drain_dfs_messages(&mut owner_transport)
        .into_iter()
        .find_map(|message| match message {
            DfsNetworkMessage::CommitVersionResponse(response) => Some(response),
            _ => None,
        })
        .expect("commit response");
    assert!(matches!(
        response.result,
        DfsBlobTransferResult::Rejected { ref reason }
            if !dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    assert!(
        target
            .metadata_backend()
            .expect("target backend")
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("unchanged receipts")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "a non-authority cannot retire or prune the durable receipt"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn missing_local_commit_content_on_retiring_primary_with_pending_handoff_stays_retryable() {
    let root = temp_root("missing-commit-content-retiring-primary-handoff");
    let fixture = seed_durable_commit_promotion_fixture(&root, "retiring-primary-handoff");
    let retiring = DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "services".to_string(),
        primary_node_id: fixture.replica.clone(),
        replica_node_ids: vec![fixture.owner.clone()],
        epoch: 1,
        assignment: DfsMetadataShardAssignment::PathPrefix {
            prefix: "/services".to_string(),
        },
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    let desired = DfsMetadataShardConfig {
        primary_node_id: fixture.owner.clone(),
        replica_node_ids: vec![fixture.replica.clone()],
        epoch: retiring.epoch + 1,
        ..retiring.clone()
    };
    let (range_started_tx, range_started_rx) = std::sync::mpsc::sync_channel(1);
    let shared_kv = SharedDfsControlPlaneKvClient::new(RangeSignalingControlPlaneKvClient::new(
        range_started_tx,
    ));
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig {
                file_system_id: sifs_file_system_id(),
                display_name: "SIFS".to_string(),
                owner_node_id: fixture.owner.clone(),
                subtree_policies: Vec::new(),
            })
            .expect("filesystem config");
        control
            .put_metadata_shard(&retiring)
            .expect("retiring services shard");
    });

    let network = InProcessNetwork::new();
    let mut owner_transport = network.add_node(fixture.owner.clone());
    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("target metadata backend");
    let mut target = NetworkedDfsService::new(
        network.add_node(fixture.replica.clone()),
        LocalContentStore::new(root.join("target-content")).expect("empty target content"),
    )
    .with_control_plane(shared_kv.clone())
    .with_metadata_backend(backend)
    .expect("target metadata hydration");
    let object_metadata = target
        .metadata()
        .object(&fixture.object_id)
        .cloned()
        .expect("committed object metadata");

    // Hold the shard publication guard so the transition can complete its
    // initial shard selection but cannot certify authority yet. Beginning the
    // handoff at that exact point proves that certification runs under the
    // guard and observes the newly durable marker before any receipt prune.
    let publication_guard = crate::service_replica::metadata_shard_publication_guard(
        &retiring.file_system_id,
        &retiring.shard_id,
    );
    shared_kv.with_client(|kv| kv.arm());
    let transition_object_id = fixture.object_id.clone();
    let transition_version = fixture.target_version.clone();
    let transition_content_hash = fixture.content_hash.clone();
    let transition = std::thread::spawn(move || {
        let transitioned = target
            .transition_missing_local_commit_content_to_repair(
                &transition_object_id,
                &transition_version,
                &transition_content_hash,
            )
            .expect("missing-content transition");
        (target, transitioned)
    });
    range_started_rx
        .recv_timeout(Duration::from_secs(2))
        .expect("transition reached guarded shard selection");
    shared_kv.with_client(|kv| {
        DfsControlPlaneStore::new(kv)
            .begin_metadata_shard_membership_handoff(&retiring, &desired)
            .expect("begin primary handoff while transition is fenced")
            .expect("pending primary handoff");
    });
    drop(publication_guard);
    let (mut target, transitioned) = transition.join().expect("join guarded transition");
    assert!(
        !transitioned,
        "a handoff that starts before certification must keep the transition retryable"
    );

    let event = target
        .handle_commit_version(
            fixture.owner.clone(),
            DfsCommitVersionCommand {
                request_id: "commit_missing_content_retiring_primary_handoff".to_string(),
                intent_id: fixture.intent_id.clone(),
                file_system_id: object_metadata.file_system_id.clone(),
                object_id: fixture.object_id.clone(),
                expected_base_version: None,
                version: fixture.target_version.clone(),
                content_hash: fixture.content_hash.clone(),
                object_metadata: Some(object_metadata),
                authority_shard: None,
            },
        )
        .expect("retryable pending-handoff response");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RepairRejected { ref reason, .. }
            if !dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    let response = drain_dfs_messages(&mut owner_transport)
        .into_iter()
        .find_map(|message| match message {
            DfsNetworkMessage::CommitVersionResponse(response) => Some(response),
            _ => None,
        })
        .expect("commit response");
    assert!(matches!(
        response.result,
        DfsBlobTransferResult::Rejected { ref reason }
            if !dfs_rejection_is_commit_content_repair_pending(
                reason,
                &fixture.object_id,
                &fixture.target_version,
                &fixture.content_hash,
            )
    ));
    assert!(
        target
            .metadata_backend()
            .expect("target backend")
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("unchanged receipts")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "a pending handoff must fence the stale primary before it prunes the durable receipt"
    );
    assert!(
        target
            .metadata_backend()
            .expect("target backend")
            .get_object(&fixture.object_id)
            .expect("object")
            .expect("object")
            .current_locations
            .contains(&fixture.replica),
        "a pending handoff must preserve the stale primary location until current authority repairs it"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn missing_local_commit_content_reselects_guard_when_object_moves_shards_before_certification() {
    let root = temp_root("missing-commit-content-shard-reselection");
    let fixture = seed_durable_commit_promotion_fixture(&root, "shard-reselection");
    let initial_shard = DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "services".to_string(),
        primary_node_id: fixture.replica.clone(),
        replica_node_ids: vec![fixture.owner.clone()],
        epoch: 1,
        assignment: DfsMetadataShardAssignment::PathPrefix {
            prefix: "/services".to_string(),
        },
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    let (range_started_tx, range_started_rx) = std::sync::mpsc::sync_channel(1);
    let shared_kv = SharedDfsControlPlaneKvClient::new(RangeSignalingControlPlaneKvClient::new(
        range_started_tx,
    ));
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig {
                file_system_id: sifs_file_system_id(),
                display_name: "SIFS".to_string(),
                owner_node_id: fixture.owner.clone(),
                subtree_policies: Vec::new(),
            })
            .expect("filesystem config");
        control
            .put_metadata_shard(&initial_shard)
            .expect("initial services shard");
    });

    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("target metadata backend");
    let mut target = NetworkedDfsService::new(
        ReceiveOnlyTransport::new(fixture.replica.clone()),
        LocalContentStore::new(root.join("target-content")).expect("empty target content"),
    )
    .with_control_plane(shared_kv.clone())
    .with_metadata_backend(backend)
    .expect("target metadata hydration");
    let object_path = target
        .metadata()
        .object(&fixture.object_id)
        .expect("committed object metadata")
        .path
        .clone();
    let moved_shard = DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "services-recovery-object".to_string(),
        primary_node_id: fixture.replica.clone(),
        replica_node_ids: vec![fixture.owner.clone()],
        epoch: 1,
        assignment: DfsMetadataShardAssignment::PathPrefix {
            prefix: object_path,
        },
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };

    let initial_guard = crate::service_replica::metadata_shard_publication_guard(
        &initial_shard.file_system_id,
        &initial_shard.shard_id,
    );
    shared_kv.with_client(|kv| kv.arm());
    let transition_object_id = fixture.object_id.clone();
    let transition_version = fixture.target_version.clone();
    let transition_content_hash = fixture.content_hash.clone();
    let transition = std::thread::spawn(move || {
        let transitioned = target
            .transition_missing_local_commit_content_to_repair(
                &transition_object_id,
                &transition_version,
                &transition_content_hash,
            )
            .expect("missing-content transition");
        (target, transitioned)
    });
    range_started_rx
        .recv_timeout(Duration::from_secs(2))
        .expect("transition selected the initial shard");
    shared_kv.with_client(|kv| {
        DfsControlPlaneStore::new(kv)
            .put_metadata_shard(&moved_shard)
            .expect("publish more-specific object shard");
    });
    drop(initial_guard);

    let (target, transitioned) = transition.join().expect("join guarded transition");
    assert!(
        transitioned,
        "stable current authority should complete after reacquiring the moved shard guard"
    );
    assert!(
        shared_kv.with_client(|kv| kv.metadata_shard_range_count()) >= 4,
        "a changed certified shard key must force guarded selection and certification to repeat"
    );
    assert!(
        !target
            .metadata_backend()
            .expect("target backend")
            .receipts_for_version(&fixture.object_id, &fixture.target_version)
            .expect("receipts after transition")
            .iter()
            .any(|receipt| receipt.replica_node_id == fixture.replica),
        "the receipt may be pruned only after the moved shard is guarded and certified"
    );
    std::fs::remove_dir_all(root).ok();
}

fn recovery_hydration_node_transport(
    owner: NodeId,
    replica: NodeId,
    detached_send_state: DfsNodeDetachedSendState,
) -> DfsNodeTransport {
    let peer = Arc::new(RecordingPeerTransport::default());
    let sync_peer: Arc<dyn DfsPeerTransport> = peer.clone();
    let async_peer = recording_async_peer_transport(peer);
    DfsNodeTransport::with_peer_transports_for_nodes_and_detached_state(
        owner,
        vec![replica],
        Duration::from_secs(1),
        sync_peer,
        async_peer,
        detached_send_state,
    )
}

#[test]
fn default_node_transport_hydration_does_not_enable_early_response_or_queue_promotions() {
    let root = temp_root("default-node-hydration-no-promotion-recovery");
    let fixture = seed_durable_commit_promotion_fixture(&root, "default");
    let detached_send_state = DfsNodeDetachedSendState::new();
    let transport = recovery_hydration_node_transport(
        fixture.owner.clone(),
        fixture.replica,
        detached_send_state.clone(),
    );
    assert!(
        !transport.can_return_committed_foreground_response_before_replica_repair(),
        "sharing an outbox must not opt an ordinary node transport into served-message semantics"
    );
    let backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("owner"), &fixture.metadata_root)
            .expect("reopened metadata backend");
    let _service = NetworkedDfsService::new(
        transport,
        LocalContentStore::new(fixture.content_root).expect("reopened content"),
    )
    .with_metadata_backend(backend)
    .expect("ordinary hydration");

    assert_eq!(
        detached_send_state.queued_send_count(),
        0,
        "ordinary node hydration must retain its foreground semantics"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
