#[test]
fn remote_read_content_mismatch_prunes_stale_location() {
    let root = temp_root("remote-read-mismatch-prunes-location");
    let reader = NodeId::from_legacy_named("node_read_mismatch_reader").expect("node");
    let source = NodeId::from_legacy_named("node_read_mismatch_source").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_read_mismatch").expect("object");
    let version = DfsVersion::from_legacy_named("version_2").expect("version");
    let expected_hash = content_hash(b"expected remote bytes");
    let request_id = "dfs_net_req_read_mismatch".to_string();
    let mut dfs = networked_sifs_with_backend(&root, reader.clone());
    let mut object = file_metadata(source.clone());
    object.object_id = object_id.clone();
    object.version = version.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![source.clone()];
    object.content_hash = Some(expected_hash.clone());
    object.content_size_bytes = Some(b"expected remote bytes".len() as u64);
    dfs.add_object_metadata(object).expect("object metadata");
    dfs.pending_reads.insert(
        request_id.clone(),
        PendingNetworkedRead {
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some(expected_hash.clone()),
            content_size_bytes: Some(b"expected remote bytes".len() as u64),
            range_offset: None,
            range_max_bytes: None,
            target_node_id: source.clone(),
            next_retry_at: Instant::now() + DFS_REMOTE_READ_RETRY_DELAY,
            cache_response: true,
        },
    );

    let event = dfs
        .handle_networked_read_response(
            source.clone(),
            DfsReadResponse {
                request_id: request_id.clone(),
                object_id: object_id.clone(),
                result: DfsReadResult::Found(DfsReadData {
                    object_id: object_id.clone(),
                    version: version.clone(),
                    content_hash: Some(expected_hash),
                    bytes: b"corrupt remote bytes".to_vec(),
                }),
            },
        )
        .expect("mismatch handled");
    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RemoteReadCompleted {
            request_id: completed_request_id,
            source_node_id,
            result: DfsReadResult::Rejected { reason },
            ..
        } if completed_request_id == request_id
            && source_node_id == source
            && reason.contains("content hash mismatch")
    ));
    assert!(!dfs.pending_reads.contains_key(&request_id));
    let object = dfs
        .current_read_object_metadata(&object_id)
        .expect("current metadata");
    assert!(
        !object.current_locations.contains(&source),
        "source that returned bytes failing content validation should be pruned"
    );
    assert_eq!(
        dfs.request_remote_object_read(&object_id)
            .expect("no stale source to retry"),
        Vec::<NodeId>::new()
    );
    std::fs::remove_dir_all(root).ok();
}

fn assert_malformed_remote_range_rejected(
    name: &str,
    mutate: impl FnOnce(&mut DfsReadRangeData),
    expected_reason: &str,
) {
    let root = temp_root(name);
    let reader = NodeId::from_legacy_named(&format!("{name}_reader")).expect("reader node");
    let source = NodeId::from_legacy_named(&format!("{name}_source")).expect("source node");
    let object_id = DfsObjectId::from_legacy_named(&format!("{name}_object")).expect("object");
    let version = DfsVersion::from_legacy_named(&format!("{name}_version")).expect("version");
    let bytes = b"authoritative ranged response bytes".to_vec();
    let content_hash = content_hash(&bytes);
    let offset = 3_u64;
    let max_bytes = 7_usize;
    let request_id = format!("{name}_request");
    let mut dfs = networked_sifs_with_backend(&root, reader);
    let mut object = file_metadata(source.clone());
    object.object_id = object_id.clone();
    object.version = version.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![source.clone()];
    object.content_hash = Some(content_hash.clone());
    object.content_size_bytes = Some(bytes.len() as u64);
    dfs.add_object_metadata(object).expect("object metadata");
    dfs.pending_reads.insert(
        request_id.clone(),
        PendingNetworkedRead {
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some(content_hash.clone()),
            content_size_bytes: Some(bytes.len() as u64),
            range_offset: Some(offset),
            range_max_bytes: Some(max_bytes),
            target_node_id: source.clone(),
            next_retry_at: Instant::now() + DFS_REMOTE_READ_RETRY_DELAY,
            cache_response: false,
        },
    );
    let start = offset as usize;
    let mut data = DfsReadRangeData {
        object_id: object_id.clone(),
        version,
        content_hash: Some(content_hash),
        offset,
        total_size_bytes: bytes.len() as u64,
        bytes: bytes[start..start + max_bytes].to_vec(),
    };
    mutate(&mut data);

    let event = dfs
        .handle_networked_read_response(
            source.clone(),
            DfsReadResponse {
                request_id: request_id.clone(),
                object_id: object_id.clone(),
                result: DfsReadResult::RangeFound(data),
            },
        )
        .expect("malformed range response handled");

    assert!(matches!(
        event,
        NetworkedDfsServiceEvent::RemoteReadCompleted {
            request_id: completed_request_id,
            result: DfsReadResult::Rejected { reason },
            ..
        } if completed_request_id == request_id && reason.contains(expected_reason)
    ));
    assert!(!dfs.pending_reads.contains_key(&request_id));
    assert!(
        !dfs.current_read_object_metadata(&object_id)
            .expect("current metadata")
            .current_locations
            .contains(&source),
        "source returning malformed range metadata must be pruned"
    );
}

#[test]
fn remote_range_rejects_wrong_version() {
    assert_malformed_remote_range_rejected(
        "range_wrong_version",
        |data| {
            data.version =
                DfsVersion::from_legacy_named("range_wrong_version_other").expect("version")
        },
        "expected version",
    );
}

#[test]
fn remote_range_rejects_wrong_offset() {
    assert_malformed_remote_range_rejected(
        "range_wrong_offset",
        |data| data.offset += 1,
        "offset mismatch",
    );
}

#[test]
fn remote_range_rejects_short_length() {
    assert_malformed_remote_range_rejected(
        "range_short_length",
        |data| {
            data.bytes.pop();
        },
        "length mismatch",
    );
}

#[test]
fn remote_range_rejects_wrong_total_size() {
    assert_malformed_remote_range_rejected(
        "range_wrong_total",
        |data| data.total_size_bytes += 1,
        "does not match object metadata",
    );
}

#[test]
fn remote_range_rejects_wrong_content_hash() {
    assert_malformed_remote_range_rejected(
        "range_wrong_hash",
        |data| data.content_hash = Some("blake3:wrong-range-hash".to_string()),
        "expected content hash",
    );
}

#[test]
fn complete_remote_range_content_mismatch_prunes_stale_location() {
    let root = temp_root("remote-range-read-mismatch-prunes-location");
    let reader = NodeId::from_legacy_named("node_range_mismatch_reader").expect("node");
    let source = NodeId::from_legacy_named("node_range_mismatch_source").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_range_mismatch").expect("object");
    let version = DfsVersion::from_legacy_named("version_range_mismatch").expect("version");
    let expected_bytes = b"expected remote range bytes".to_vec();
    let expected_hash = content_hash(&expected_bytes);
    let mut corrupt_bytes = expected_bytes.clone();
    corrupt_bytes[0] ^= 0xff;
    let request_id = "dfs_net_req_range_mismatch".to_string();
    let mut dfs = networked_sifs_with_backend(&root, reader);
    let mut object = file_metadata(source.clone());
    object.object_id = object_id.clone();
    object.version = version.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations = vec![source.clone()];
    object.content_hash = Some(expected_hash.clone());
    object.content_size_bytes = Some(expected_bytes.len() as u64);
    dfs.add_object_metadata(object).expect("object metadata");
    dfs.pending_reads.insert(
        request_id.clone(),
        PendingNetworkedRead {
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some(expected_hash.clone()),
            content_size_bytes: Some(expected_bytes.len() as u64),
            range_offset: Some(0),
            range_max_bytes: Some(expected_bytes.len()),
            target_node_id: source.clone(),
            next_retry_at: Instant::now() + DFS_REMOTE_READ_RETRY_DELAY,
            cache_response: false,
        },
    );

    let error = dfs
        .handle_networked_read_response(
            source.clone(),
            DfsReadResponse {
                request_id: request_id.clone(),
                object_id: object_id.clone(),
                result: DfsReadResult::RangeFound(DfsReadRangeData {
                    object_id: object_id.clone(),
                    version,
                    content_hash: Some(expected_hash),
                    offset: 0,
                    total_size_bytes: expected_bytes.len() as u64,
                    bytes: corrupt_bytes,
                }),
            },
        )
        .expect_err("mismatched complete range must retain its typed error");

    assert!(matches!(
        error,
        DfsError::ContentHashMismatch { expected, .. } if expected == content_hash(&expected_bytes)
    ));
    assert!(!dfs.pending_reads.contains_key(&request_id));
    assert!(
        !dfs.current_read_object_metadata(&object_id)
            .expect("current metadata")
            .current_locations
            .contains(&source),
        "source returning same-size corrupt range bytes must be pruned"
    );
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn remote_read_location_prune_updates_stale_backend_version_record() {
    let root = temp_root("read-prune-updates-version-record");
    let reader = NodeId::from_legacy_named("node_read_prune_reader").expect("node");
    let source = NodeId::from_legacy_named("node_read_prune_source").expect("node");
    let object_id = DfsObjectId::from_legacy_named("obj_read_prune_version").expect("object");
    let version = DfsVersion::from_legacy_named("version_2").expect("version");
    let hash = content_hash(b"version-location bytes");
    let mut dfs = networked_sifs_with_backend(&root, reader);
    let mut object = file_metadata(source.clone());
    object.object_id = object_id.clone();
    object.version = version.clone();
    object.policy = DfsObjectPolicy::ReplicatedEventual;
    object.current_locations.clear();
    object.content_hash = Some(hash.clone());
    object.content_size_bytes = Some(b"version-location bytes".len() as u64);
    dfs.add_object_metadata(object.clone())
        .expect("object metadata");
    dfs.metadata_backend
        .as_mut()
        .expect("backend")
        .put_version(&DfsObjectVersionRecord {
            file_system_id: object.file_system_id.clone(),
            object_id: object_id.clone(),
            version: version.clone(),
            content_hash: Some(hash.clone()),
            size_bytes: object.content_size_bytes,
            locations: vec![source.clone()],
            created_by_event_id: None,
            created_at: OffsetDateTime::UNIX_EPOCH,
            visible: true,
        })
        .expect("stale version locations");
    dfs.metadata_backend
        .as_mut()
        .expect("backend")
        .put_receipt(&DfsReplicaReceiptRecord {
            receipt: DfsWriteReceipt {
                file_system_id: object.file_system_id.clone(),
                object_id: object_id.clone(),
                committed_version: version.clone(),
                owner_node_id: source.clone(),
                event_id: EventId::from_legacy_named("evt_read_prune_stale_receipt")
                    .expect("event"),
            },
            replica_node_id: source.clone(),
            content_hash: Some(hash.clone()),
            received_at: OffsetDateTime::UNIX_EPOCH,
        })
        .expect("stale receipt");

    dfs.mark_remote_read_location_missing(&object_id, &version, &Some(hash), &source)
        .expect("prune stale version location");

    assert_eq!(
        dfs.metadata_backend
            .as_ref()
            .expect("backend")
            .get_object(&object_id)
            .expect("backend object")
            .expect("backend object")
            .current_locations,
        Vec::<NodeId>::new()
    );
    assert_eq!(
        dfs.metadata_backend
            .as_ref()
            .expect("backend")
            .get_version(&object_id, &version)
            .expect("backend version")
            .expect("backend version")
            .locations,
        Vec::<NodeId>::new()
    );
    assert!(
        dfs.metadata_backend
            .as_ref()
            .expect("backend")
            .receipts_for_version(&object_id, &version)
            .expect("backend receipts")
            .is_empty(),
        "authoritative stale-location prune should remove the matching receipt"
    );
    std::fs::remove_dir_all(root).ok();
}

