#[test]
fn lazy_metadata_hydration_restores_running_cross_shard_mutation_guards() {
    let root = temp_root("lazy-metadata-cross-shard-mutation-guards");
    let node = NodeId::from_legacy_named("node_lazy_cross_shard_guards").expect("node");
    let file_system = distributed_sifs(node.clone());
    let guarded_root = "/services/guarded-tree";
    let now = OffsetDateTime::now_utc();
    let job = DfsNamespaceJobRecord {
        job_id: "running-cross-shard-rename".to_string(),
        file_system_id: file_system.file_system_id.clone(),
        kind: DfsNamespaceJobKind::RenameDirectoryAcrossShardPrimaries,
        status: DfsNamespaceJobStatus::Running,
        root_path: guarded_root.to_string(),
        target_path: Some("/users/guarded-tree".to_string()),
        pending_frames: Vec::new(),
        processed_object_count: 0,
        created_at: now,
        updated_at: now,
        completed_at: None,
        failure_reason: None,
    };
    let metadata_root = root.join("metadata");
    let mut backend =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), &metadata_root)
            .expect("metadata backend");
    backend.put_file_system(&file_system).expect("filesystem");
    backend.put_namespace_job(&job).expect("namespace job");
    drop(backend);

    let service = NetworkedDfsService::new(
        InProcessNetwork::new().add_node(node),
        LocalContentStore::new(root.join("content")).expect("content"),
    )
    .with_metadata_backend_lazy(
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), metadata_root)
            .expect("reopened metadata backend"),
    )
    .expect("lazy metadata service");

    assert!(matches!(
        service.ensure_path_not_in_cross_shard_flight(
            &file_system.file_system_id,
            "/services/guarded-tree/child.txt",
        ),
        Err(DfsError::Busy { .. })
    ));
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn cold_lazy_sync_path_includes_durable_direct_child_tombstones() {
    let root = temp_root("cold-lazy-sync-path-tombstones");
    let node = NodeId::from_legacy_named("node_cold_lazy_sync_primary").expect("node");
    let requester = NodeId::from_legacy_named("node_cold_lazy_sync_requester").expect("requester");
    let directory = "/services/cold-sync-dir";
    let deleted_path = "/services/cold-sync-dir/deleted.txt";
    let sender: DfsMessageSender = Arc::new(|_, command, _| {
        Ok(DfsMessageResponse {
            request_id: command.request_id.clone(),
            outbound_messages: Vec::new(),
        })
    });
    {
        let mut writer = NetworkedDfsService::new(
            DfsNodeServedMessageTransport::new_with_message_sender(
                node.clone(),
                Vec::new(),
                Arc::clone(&sender),
                Duration::from_secs(1),
            ),
            LocalContentStore::new(root.join("content")).expect("writer content"),
        )
        .with_metadata_backend(
            LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), root.join("metadata"))
                .expect("writer metadata backend"),
        )
        .expect("writer metadata service");
        writer.bootstrap_distributed_sifs().expect("bootstrap sifs");
        writer.posix_mkdir_all(directory).expect("directory");
        writer
            .posix_write_file(
                deleted_path,
                b"deleted payload",
                DfsWriteOptions::replicated_eventual(vec![node.clone()]),
            )
            .expect("write deleted child");
        writer.posix_unlink(deleted_path).expect("unlink child");
    }

    let mut cold = NetworkedDfsService::new(
        DfsNodeServedMessageTransport::new_with_message_sender(
            node.clone(),
            Vec::new(),
            sender,
            Duration::from_secs(1),
        ),
        LocalContentStore::new(root.join("content")).expect("cold content"),
    )
    .with_metadata_backend_lazy(
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), root.join("metadata"))
            .expect("cold metadata backend"),
    )
    .expect("cold lazy service");
    let routed_message = build_dfs_routed_message(
        &requester,
        &node,
        1,
        1,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "cold-lazy-sync-path".to_string(),
            file_system_id: sifs_file_system_id(),
            requesting_node_id: requester.clone(),
            include_metadata_journal_batches: false,
            metadata_journal_after_sequences: Vec::new(),
            authority_shards: Vec::new(),
            operation: DfsNamespaceOperation::SyncPath {
                path: directory.to_string(),
            },
        }),
    );
    let result = cold
        .process_message_command(test_dfs_message_command(
            "cold_lazy_sync_path_rpc",
            routed_message,
        ))
        .expect("cold SyncPath");

    assert!(result.response.outbound_messages.iter().any(|message| {
        matches!(
            &message.message,
            DfsNetworkMessage::NamespaceResponse(DfsNamespaceResponse {
                synced_path_objects,
                ..
            }) if synced_path_objects.iter().any(|object| {
                object.path == deleted_path && object.kind == DfsObjectKind::Tombstone
            })
        )
    }));

    let mut live_overlay =
        LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), root.join("metadata"))
            .expect("overlay metadata backend")
            .get_object_by_path(&sifs_file_system_id(), deleted_path)
            .expect("read durable tombstone")
            .expect("durable tombstone");
    assert_eq!(live_overlay.kind, DfsObjectKind::Tombstone);
    let stale_tombstone = live_overlay.clone();
    live_overlay.kind = DfsObjectKind::File;
    live_overlay.version = DfsVersion::generate();
    live_overlay.content_hash = Some(content_hash(b"newer transient live child"));
    live_overlay.content_size_bytes = Some(b"newer transient live child".len() as u64);
    cold.add_transient_object_metadata(live_overlay.clone())
        .expect("newer live overlay");
    let routed_message = build_dfs_routed_message(
        &requester,
        &node,
        2,
        2,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "cold-lazy-sync-path-live-overlay".to_string(),
            file_system_id: sifs_file_system_id(),
            requesting_node_id: requester.clone(),
            include_metadata_journal_batches: false,
            metadata_journal_after_sequences: Vec::new(),
            authority_shards: Vec::new(),
            operation: DfsNamespaceOperation::SyncPath {
                path: directory.to_string(),
            },
        }),
    );
    let result = cold
        .process_message_command(test_dfs_message_command(
            "cold_lazy_sync_path_live_overlay_rpc",
            routed_message,
        ))
        .expect("cold SyncPath with live overlay");
    let synced_children = result
        .response
        .outbound_messages
        .iter()
        .filter_map(|message| match &message.message {
            DfsNetworkMessage::NamespaceResponse(response) => Some(&response.synced_path_objects),
            _ => None,
        })
        .flatten()
        .filter(|object| object.path == deleted_path)
        .collect::<Vec<_>>();
    assert_eq!(
        synced_children.len(),
        1,
        "SyncPath must return exactly one authoritative child per path"
    );
    assert_eq!(synced_children[0].kind, DfsObjectKind::Tombstone);
    assert_eq!(synced_children[0].version, stale_tombstone.version);

    cold.remove_transient_object_metadata(&live_overlay.object_id);
    cold.track_metadata_tombstone(&stale_tombstone);
    let mut durable_live = live_overlay;
    durable_live.version = DfsVersion::generate();
    durable_live.content_hash = Some(content_hash(b"newer durable live child"));
    durable_live.content_size_bytes = Some(b"newer durable live child".len() as u64);
    LocalSobjMetadataBackend::new(DfsMetadataShardId::new("root"), root.join("metadata"))
        .expect("durable live metadata backend")
        .put_object(&durable_live)
        .expect("newer durable live child");
    let routed_message = build_dfs_routed_message(
        &requester,
        &node,
        3,
        3,
        DfsNetworkMessage::NamespaceRequest(DfsNamespaceCommand {
            request_id: "cold-lazy-sync-path-durable-live".to_string(),
            file_system_id: sifs_file_system_id(),
            requesting_node_id: requester.clone(),
            include_metadata_journal_batches: false,
            metadata_journal_after_sequences: Vec::new(),
            authority_shards: Vec::new(),
            operation: DfsNamespaceOperation::SyncPath {
                path: directory.to_string(),
            },
        }),
    );
    let result = cold
        .process_message_command(test_dfs_message_command(
            "cold_lazy_sync_path_durable_live_rpc",
            routed_message,
        ))
        .expect("cold SyncPath with durable live child");
    let synced_children = result
        .response
        .outbound_messages
        .iter()
        .filter_map(|message| match &message.message {
            DfsNetworkMessage::NamespaceResponse(response) => Some(&response.synced_path_objects),
            _ => None,
        })
        .flatten()
        .filter(|object| object.path == deleted_path)
        .collect::<Vec<_>>();
    assert_eq!(
        synced_children.len(),
        1,
        "a durable live child must suppress an older in-memory tombstone"
    );
    assert_eq!(synced_children[0].kind, DfsObjectKind::File);
    assert_eq!(synced_children[0].version, durable_live.version);
    std::fs::remove_dir_all(root).ok();
}

#[test]
fn sharded_lazy_reader_refreshes_after_remote_primary_overwrite() {
    let root = temp_root("sifs-sharded-lazy-reader-remote-primary");
    let primary_node = NodeId::from_legacy_named("node_sifs_lazy_remote_primary").expect("primary");
    let writer_node = NodeId::from_legacy_named("node_sifs_lazy_remote_writer").expect("writer");
    let shards = sifs_two_primary_shard_configs(
        &primary_node,
        &primary_node,
        1,
        vec![writer_node.clone()],
        vec![writer_node.clone()],
    );
    let shared_kv = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                primary_node.clone(),
            )))
            .expect("sifs filesystem config");
        for shard in &shards {
            control.put_metadata_shard(shard).expect("metadata shard");
        }
    });
    let network = InProcessNetwork::new();
    let primary_root = root.join("primary");
    let writer_root = root.join("writer");
    let mut primary = NetworkedDfsService::new(
        network.add_node(primary_node.clone()),
        LocalContentStore::new(primary_root.join("content")).expect("primary content"),
    )
    .with_control_plane(shared_kv.clone())
    .with_metadata_backend_lazy(
        open_local_sharded_metadata_backend(primary_root.join("metadata"), shards.clone())
            .expect("primary metadata"),
    )
    .expect("primary metadata backend");
    let mut writer = NetworkedDfsService::new(
        network.add_node(writer_node.clone()),
        LocalContentStore::new(writer_root.join("content")).expect("writer content"),
    )
    .with_control_plane(shared_kv.clone())
    .with_metadata_backend_lazy(
        open_local_sharded_metadata_backend(writer_root.join("metadata"), shards.clone())
            .expect("writer metadata"),
    )
    .expect("writer metadata backend");
    primary
        .bootstrap_distributed_sifs()
        .expect("primary bootstrap");

    let deadline = Instant::now() + SIFS_CLUSTER_PUMP_DEADLINE;
    loop {
        primary
            .replicate_configured_metadata_shards(&sifs_file_system_id())
            .expect("primary publish");
        primary.process_incoming().expect("primary pump");
        writer.process_incoming().expect("writer pump");
        if writer.posix_stat(SIFS_SERVICES_PATH).is_ok() {
            break;
        }
        if Instant::now() >= deadline {
            panic!("writer did not learn SIFS services namespace");
        }
        std::thread::sleep(SIFS_CLUSTER_PUMP_IDLE_SLEEP);
    }
    writer
        .bootstrap_distributed_sifs()
        .expect("writer bootstrap");

    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        let mut primary = primary;
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    let path = "/services/current-read-remote-primary.txt";
    let old = b"old remote primary reader payload".to_vec();
    let new = b"new remote primary reader payload".to_vec();
    writer
        .posix_write_file(
            path,
            &old,
            DfsWriteOptions::replicated_eventual(vec![writer_node.clone()]),
        )
        .expect("initial remote-primary write");

    let mut reader = NetworkedDfsService::new(
        network.add_node(writer_node.clone()),
        LocalContentStore::new(writer_root.join("content")).expect("reader content"),
    )
    .with_control_plane(shared_kv)
    .with_metadata_backend_lazy(
        open_local_sharded_metadata_backend(writer_root.join("metadata"), shards)
            .expect("reader metadata"),
    )
    .expect("reader metadata backend");
    reader
        .bootstrap_distributed_sifs()
        .expect("reader bootstrap");
    assert_eq!(
        reader
            .posix_read_file_distributed(path)
            .expect("reader old payload"),
        old
    );

    writer
        .posix_write_file(
            path,
            &new,
            DfsWriteOptions::replicated_eventual(vec![writer_node]),
        )
        .expect("remote-primary overwrite");

    assert_eq!(
        reader
            .posix_read_file_distributed(path)
            .expect("reader current payload"),
        new
    );

    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_cluster_posix_contract_damaged_replica_under_concurrent_reads() {
    let mut cluster = sifs_posix_cluster("sifs-contract-damaged-replica");
    let scenario = "damaged-replica-under-concurrent-reads";
    let path = "/services/contract-damaged.bin";
    let old = vec![0x44; 64 * 1024];
    let new = vec![0x55; 64 * 1024];
    let old_hash = content_hash(&old);
    let mut observations = Vec::new();
    let initial_write = cluster.writer.posix_write_file(
        path,
        &old,
        DfsWriteOptions {
            policy: DfsReplicationPolicy::new(1, 2).expect("policy"),
            replica_candidates: vec![cluster.writer_node.clone(), cluster.primary_node.clone()],
            wait_for_commit: true,
            foreground_replica_repair: true,
        },
    );
    let initial_request = match &initial_write {
        Ok(stat) => {
            record_posix_observation(
                &mut observations,
                scenario,
                "initial-replicated-write",
                &cluster.writer_node,
                path,
                Instant::now(),
                "committed",
                Some(stat),
            );
            None
        }
        Err(DfsPosixError::PendingWrite { intent_id, .. }) => Some(intent_id.clone()),
        Err(error) => panic!("initial replicated write failed unexpectedly: {error}"),
    };
    sifs_posix_cluster_pump_until(
        &mut cluster,
        "initial replicated write settles",
        |cluster| {
            initial_request.as_ref().is_none_or(|intent| {
                !matches!(
                    cluster.writer.write_outcome(intent),
                    Ok(NetworkedDfsWriteOutcome::Pending { .. })
                )
            }) && cluster
                .writer
                .posix_stat(path)
                .is_ok_and(|stat| stat.content_hash.as_deref() == Some(old_hash.as_str()))
        },
    );
    sifs_posix_cluster_pump_until(&mut cluster, "primary gets old replica", |cluster| {
        cluster
            .primary
            .posix_read_file(path)
            .is_ok_and(|bytes| bytes == old)
    });
    cluster
        .writer
        .content
        .debug_remove_loose_blob(&old_hash)
        .expect("damage writer blob");
    cluster
        .primary
        .posix_write_file(
            path,
            &new,
            sifs_cluster_write_options(&cluster.primary_node.clone()),
        )
        .expect("primary concurrent overwrite");
    sifs_cluster_publish_metadata_until(&mut cluster, "writer sees new metadata", |cluster| {
        cluster
            .writer
            .posix_stat(path)
            .is_ok_and(|stat| stat.content_hash.as_deref() == Some(content_hash(&new).as_str()))
    });
    let read = {
        let primary = &mut cluster.primary;
        let writer = &mut cluster.writer;
        sifs_cluster_blocking_distributed_read_with_pump(
            writer,
            path,
            "read around damaged replica",
            || {
                primary.process_incoming().expect("primary pump");
            },
        )
    };
    let stat = cluster.writer.posix_stat(path).expect("writer stat");
    record_posix_observation(
        &mut observations,
        scenario,
        "damaged-current-read",
        &cluster.writer_node,
        path,
        Instant::now(),
        "read",
        Some(&stat),
    );
    assert_eq!(
        read, new,
        "current read must avoid damaged/stale local replica and fetch valid current content"
    );
    assert_sifs_cluster_no_posix_leaks(&cluster, scenario);
    finish_posix_observations(&observations);
    std::fs::remove_dir_all(&cluster.root).ok();
}

#[test]
fn sifs_cluster_posix_routed_create_is_read_your_write_on_writer() {
    let mut cluster = sifs_posix_cluster("sifs-cluster-ryw");
    let path = "/users/read-your-write.txt";
    let bytes = b"hello from the writer node";

    sifs_cluster_routed_posix_write(&mut cluster, path, bytes);

    // Read-your-write through the strictly local read path: after the routed
    // write commits, the writer must see its own bytes without any further
    // network round trip.
    assert_eq!(
        cluster.writer.posix_read_file(path).expect("writer read"),
        bytes.to_vec()
    );
    let stat = cluster.writer.posix_stat(path).expect("writer stat");
    assert_eq!(stat.kind, DfsObjectKind::File);
    assert_eq!(stat.size_bytes, Some(bytes.len() as u64));
    assert_eq!(
        stat.content_hash.as_deref(),
        Some(content_hash(bytes).as_str())
    );

    // The new entry must be listed in the parent directory on the writer.
    let entries = cluster
        .writer
        .posix_list_dir("/users")
        .expect("writer list /users");
    assert!(
        entries
            .iter()
            .any(|entry| entry.path == path && entry.kind == DfsObjectKind::File),
        "writer directory listing must contain the routed write: {entries:?}"
    );

    std::fs::remove_dir_all(&cluster.root).ok();
}

#[test]
fn sifs_cluster_posix_routed_write_is_visible_on_primary() {
    let mut cluster = sifs_posix_cluster("sifs-cluster-primary-vis");
    let path = "/users/primary-visibility.txt";
    let bytes = b"routed bytes visible on the primary";

    sifs_cluster_routed_posix_write(&mut cluster, path, bytes);

    // The shard primary serialized the write, so its metadata must already be
    // authoritative: correct kind, size, and content hash.
    let stat = cluster.primary.posix_stat(path).expect("primary stat");
    assert_eq!(stat.kind, DfsObjectKind::File);
    assert_eq!(stat.size_bytes, Some(bytes.len() as u64));
    assert_eq!(
        stat.content_hash.as_deref(),
        Some(content_hash(bytes).as_str())
    );

    let entries = cluster
        .primary
        .posix_list_dir("/users")
        .expect("primary list /users");
    assert!(
        entries.iter().any(|entry| entry.path == path),
        "primary directory listing must contain the routed write: {entries:?}"
    );

    // The content was staged on the writer; the primary must be able to make
    // it locally readable through the remote-read path.
    let read = sifs_cluster_fetch_for_local_read(&mut cluster, |c| &mut c.primary, path);
    assert_eq!(read, bytes.to_vec());

    std::fs::remove_dir_all(&cluster.root).ok();
}

#[test]
fn sifs_cluster_writer_recovers_from_local_blob_loss_after_async_repair() {
    let mut cluster = sifs_posix_cluster("sifs-cluster-writer-blob-loss");
    let path = "/services/async-repaired-writer-loss.bin";
    let bytes = (0..64 * 1024)
        .map(|index| (index % 251) as u8)
        .collect::<Vec<_>>();
    let expected_hash = content_hash(&bytes);

    match cluster.writer.posix_write_file(
        path,
        &bytes,
        DfsWriteOptions {
            policy: DfsReplicationPolicy::new(1, 2).expect("policy"),
            replica_candidates: vec![cluster.writer_node.clone(), cluster.primary_node.clone()],
            wait_for_commit: false,
            foreground_replica_repair: false,
        },
    ) {
        Ok(stat) => assert_eq!(
            stat.content_hash.as_deref(),
            Some(expected_hash.as_str()),
            "committed writer stat should expose the written content hash"
        ),
        Err(DfsPosixError::PendingWrite { .. }) => {}
        Err(error) => panic!("async routed write failed: {error}"),
    }
    sifs_posix_cluster_pump_until(&mut cluster, "writer observes async write", |cluster| {
        cluster
            .writer
            .posix_stat(path)
            .is_ok_and(|stat| stat.content_hash.as_deref() == Some(expected_hash.as_str()))
    });

    sifs_posix_cluster_pump_until(&mut cluster, "primary async repair", |cluster| {
        cluster
            .primary
            .retry_pending_repairs()
            .expect("primary repair tick");
        cluster
            .primary
            .posix_read_file(path)
            .is_ok_and(|read| read == bytes)
    });
    sifs_cluster_publish_metadata_until(
        &mut cluster,
        "writer learns repaired primary location",
        |cluster| {
            cluster.writer.posix_stat(path).is_ok_and(|stat| {
                stat.current_locations.contains(&cluster.writer_node)
                    && stat.current_locations.contains(&cluster.primary_node)
            })
        },
    );

    cluster
        .writer
        .content
        .debug_remove_loose_blob(&expected_hash)
        .expect("remove writer loose blob");
    assert!(
        matches!(
            cluster.writer.posix_read_file(path),
            Err(DfsPosixError::NotFound { .. })
        ),
        "fault injection must remove the writer's local readable content"
    );

    let recovered =
        sifs_cluster_fetch_for_local_read(&mut cluster, |cluster| &mut cluster.writer, path);
    assert_eq!(recovered, bytes);
    assert!(
        cluster.rejections.is_empty(),
        "journal replication should remain clean: {:?}",
        cluster.rejections
    );

    std::fs::remove_dir_all(&cluster.root).ok();
}

