#[test]
fn sifs_cluster_posix_rejects_adoption_from_non_source_primary() {
    let mut cluster = sifs_two_primary_cluster("sifs-xshard-rogue");
    let mut rogue_object = file_metadata(cluster.replica_node.clone());
    rogue_object.object_id = DfsObjectId::from_legacy_named("obj_rogue_adopt").expect("object");
    rogue_object.file_system_id = sifs_file_system_id();
    rogue_object.path = "/services/rogue.txt".to_string();
    rogue_object.policy = DfsObjectPolicy::ReplicatedEventual;

    // The replica is not the primary of the claimed source shard (/users is
    // owned by the users primary), so the services primary must reject the
    // injected adoption outright.
    let event = cluster
        .services_primary
        .handle_namespace_request(
            cluster.replica_node.clone(),
            DfsNamespaceCommand {
                request_id: "rogue-adopt-1".to_string(),
                file_system_id: sifs_file_system_id(),
                requesting_node_id: cluster.replica_node.clone(),
                include_metadata_journal_batches: true,
                metadata_journal_after_sequences: Vec::new(),
                authority_shards: Vec::new(),
                operation: DfsNamespaceOperation::AdoptObjectAtPath {
                    object: rogue_object,
                    source_path: "/users/rogue-src.txt".to_string(),
                    versions: Vec::new(),
                    receipts: Vec::new(),
                    intents: Vec::new(),
                    conflicts: Vec::new(),
                    advisory_lock_state: None,
                },
            },
        )
        .expect("handler must answer");
    let NetworkedDfsServiceEvent::RemoteNamespaceServed { result, .. } = event else {
        panic!("expected a served event, got {event:?}");
    };
    let DfsNamespaceResult::Rejected { reason, .. } = result else {
        panic!("rogue adoption must be rejected, got {result:?}");
    };
    assert!(
        reason.contains("is not the primary of source shard"),
        "unexpected rejection reason: {reason}"
    );
    assert!(matches!(
        cluster.services_primary.posix_stat("/services/rogue.txt"),
        Err(DfsPosixError::NotFound { .. })
    ));

    std::fs::remove_dir_all(&cluster.root).ok();
}

#[test]
fn sifs_cluster_posix_cross_shard_resume_honors_step_budget() {
    let mut cluster = sifs_two_primary_cluster("sifs-xshard-budget");
    let ghost = NodeId::from_legacy_named("node_sifs_xshard_budget_ghost").expect("ghost");
    let local_options = DfsWriteOptions {
        policy: DfsReplicationPolicy::new(1, 1).expect("policy"),
        replica_candidates: vec![cluster.users_primary_node.clone()],
        wait_for_commit: true,
        foreground_replica_repair: true,
    };
    cluster
        .users_primary
        .posix_mkdir("/users/budget-dir")
        .expect("mkdir");
    for index in 0..3 {
        cluster
            .users_primary
            .posix_write_file(
                &format!("/users/budget-dir/file-{index}.txt"),
                format!("budget {index}").as_bytes(),
                local_options.clone(),
            )
            .expect("create child");
    }

    // Park the subtree move against an unreachable destination primary.
    let to_ghost = sifs_two_primary_shard_configs(
        &cluster.users_primary_node,
        &ghost,
        5,
        vec![
            cluster.services_primary_node.clone(),
            cluster.replica_node.clone(),
        ],
        vec![
            cluster.users_primary_node.clone(),
            cluster.replica_node.clone(),
        ],
    );
    cluster.shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        for shard in &to_ghost {
            control.put_metadata_shard(shard).expect("ghost shard");
        }
    });
    cluster
        .users_primary
        .posix_rename("/users/budget-dir", "/services/budget-dir")
        .expect_err("park against the ghost primary");

    // Heal and resume with a one-step budget: completion must take multiple
    // bounded rounds instead of one unbounded run.
    let healed = sifs_two_primary_shard_configs(
        &cluster.users_primary_node,
        &cluster.services_primary_node,
        6,
        vec![
            cluster.services_primary_node.clone(),
            cluster.replica_node.clone(),
        ],
        vec![
            cluster.users_primary_node.clone(),
            cluster.replica_node.clone(),
        ],
    );
    cluster.shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        for shard in &healed {
            control.put_metadata_shard(shard).expect("healed shard");
        }
    });
    let services_primary = std::mem::replace(
        &mut cluster.services_primary,
        NetworkedDfsService::new(
            sinomo_core::network::InProcessNetwork::new()
                .add_node(NodeId::from_legacy_named("node_unused_pump4").expect("node")),
            LocalContentStore::new(cluster.root.join("unused-content")).expect("content"),
        ),
    );
    let stop = Arc::new(AtomicBool::new(false));
    let services_stop = Arc::clone(&stop);
    let services_thread =
        std::thread::spawn(move || pump_sifs_service_until_stop(services_primary, services_stop));

    let first = cluster
        .users_primary
        .posix_resume_namespace_jobs_bounded(8, 1)
        .expect("budgeted resume");
    assert_eq!(
        (first.resumed_job_count, first.remaining_running_job_count),
        (1, 1),
        "a one-step budget must leave the saga running: {first:?}"
    );
    let mut rounds = 1usize;
    loop {
        let report = cluster
            .users_primary
            .posix_resume_namespace_jobs_bounded(8, 1)
            .expect("budgeted resume round");
        rounds += 1;
        if report.completed_job_count == 1 {
            break;
        }
        assert!(rounds < 64, "budgeted resume did not converge");
    }
    assert!(
        rounds >= 3,
        "three children plus root must take several one-step rounds"
    );
    stop.store(true, Ordering::SeqCst);
    cluster.services_primary = services_thread.join().expect("services thread");

    assert!(matches!(
        cluster.users_primary.posix_stat("/users/budget-dir"),
        Err(DfsPosixError::NotFound { .. })
    ));
    for index in 0..3 {
        assert!(
            cluster
                .users_primary
                .posix_stat(&format!("/services/budget-dir/file-{index}.txt"))
                .is_ok(),
            "child {index} must have moved"
        );
    }

    std::fs::remove_dir_all(&cluster.root).ok();
}

#[test]
fn sifs_cluster_authority_local_follower_bootstrap_stays_on_incremental_stream() {
    // Bootstrap objects are authority-local. A follower may open/bootstrap its
    // service independently, but it must not manufacture a divergent namespace
    // journal that forces an avoidable full snapshot before ordinary catch-up.
    let root = temp_root("sifs-authority-local-bootstrap-incremental");
    let primary_node = NodeId::from_legacy_named("node_inservice_snap_primary").expect("primary");
    let follower_node =
        NodeId::from_legacy_named("node_inservice_snap_follower").expect("follower");
    let network = InProcessNetwork::new();
    let shared_kv = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                primary_node.clone(),
            )))
            .expect("fs config");
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: sifs_file_system_id(),
                shard_id: "root".to_string(),
                primary_node_id: primary_node.clone(),
                replica_node_ids: vec![follower_node.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::Root,
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("shard config");
    });
    let node = |node_id: &NodeId, dir: &str| {
        let node_root = root.join(dir);
        let mut dfs = NetworkedDfsService::new(
            network.add_node(node_id.clone()),
            LocalContentStore::new(node_root.join("content")).expect("content"),
        )
        .with_control_plane(shared_kv.clone())
        .with_metadata_backend(
            open_root_local_metadata_backend(node_root.join("metadata")).expect("metadata"),
        )
        .expect("backend attach");
        // Both services open independently. Only the configured primary may
        // create the fixed namespace anchors.
        dfs.bootstrap_distributed_sifs().expect("bootstrap");
        dfs
    };
    let mut primary = node(&primary_node, "primary");
    let mut follower = node(&follower_node, "follower");
    assert_eq!(
        follower
            .metadata_backend()
            .expect("follower metadata backend")
            .journal_last_sequence()
            .expect("follower bootstrap journal head"),
        0,
        "a non-primary bootstrap must leave its durable metadata journal at genesis"
    );

    let bytes = b"post-repair payload".to_vec();
    primary
        .posix_write_file(
            "/users/after-repair.txt",
            &bytes,
            DfsWriteOptions {
                policy: DfsReplicationPolicy::new(1, 1).expect("policy"),
                replica_candidates: vec![primary_node.clone()],
                wait_for_commit: true,
                foreground_replica_repair: true,
            },
        )
        .expect("primary create");

    let mut saw_snapshot_install = false;
    let expected_hash = content_hash(&bytes);
    let deadline = Instant::now() + SIFS_CLUSTER_PUMP_DEADLINE;
    loop {
        primary
            .replicate_configured_metadata_shards(&sifs_file_system_id())
            .expect("publish");
        for service in [&mut primary, &mut follower] {
            for event in service.process_incoming().expect("pump") {
                if matches!(
                    event,
                    NetworkedDfsServiceEvent::MetadataSnapshotInstalled { .. }
                ) {
                    saw_snapshot_install = true;
                }
            }
        }
        if follower
            .posix_stat("/users/after-repair.txt")
            .is_ok_and(|stat| stat.content_hash.as_deref() == Some(expected_hash.as_str()))
        {
            break;
        }
        if Instant::now() >= deadline {
            panic!("authority-local follower did not converge through incremental publication");
        }
        std::thread::sleep(SIFS_CLUSTER_PUMP_IDLE_SLEEP);
    }
    assert!(
        !saw_snapshot_install,
        "authority-local follower bootstrap must not force a full metadata snapshot"
    );

    // Post-repair, the follower applies regular journal batches cleanly.
    let more = b"incremental after the snapshot".to_vec();
    primary
        .posix_write_file(
            "/users/incremental.txt",
            &more,
            DfsWriteOptions {
                policy: DfsReplicationPolicy::new(1, 1).expect("policy"),
                replica_candidates: vec![primary_node.clone()],
                wait_for_commit: true,
                foreground_replica_repair: true,
            },
        )
        .expect("primary second incremental create");
    let expected_more = content_hash(&more);
    let deadline = Instant::now() + SIFS_CLUSTER_PUMP_DEADLINE;
    loop {
        primary
            .replicate_configured_metadata_shards(&sifs_file_system_id())
            .expect("publish incremental");
        primary.process_incoming().expect("primary pump");
        follower.process_incoming().expect("follower pump");
        if follower
            .posix_stat("/users/incremental.txt")
            .is_ok_and(|stat| stat.content_hash.as_deref() == Some(expected_more.as_str()))
        {
            break;
        }
        if Instant::now() >= deadline {
            panic!("follower did not remain on the incremental metadata stream");
        }
        std::thread::sleep(SIFS_CLUSTER_PUMP_IDLE_SLEEP);
    }

    std::fs::remove_dir_all(root).ok();
}

/// A 3-node SIFS cluster where `observer` is NOT in the root shard's replica
/// set: the primary is the namespace authority, `writer` receives the pushed
/// journal stream, and the outsider observer only converges its local mirror
/// through routed-response batches and SyncPath pulls.
fn sifs_outsider_cluster(name: &str) -> SifsPosixCluster {
    let root = temp_root(name);
    let node_prefix = name.replace('-', "_");
    let primary_node =
        NodeId::from_legacy_named(&format!("node_{node_prefix}_primary")).expect("primary node");
    let writer_node =
        NodeId::from_legacy_named(&format!("node_{node_prefix}_writer")).expect("writer node");
    let observer_node =
        NodeId::from_legacy_named(&format!("node_{node_prefix}_outsider")).expect("outsider node");

    let network = InProcessNetwork::new();
    let shared_kv = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    shared_kv.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                primary_node.clone(),
            )))
            .expect("sifs filesystem config");
        control
            .put_metadata_shard(&DfsMetadataShardConfig {
                file_system_id: sifs_file_system_id(),
                shard_id: "root".to_string(),
                primary_node_id: primary_node.clone(),
                replica_node_ids: vec![writer_node.clone()],
                epoch: 1,
                assignment: DfsMetadataShardAssignment::Root,
                default_policy: DfsObjectPolicy::ReplicatedEventual,
            })
            .expect("sifs root metadata shard config");
    });

    let mut primary =
        sifs_posix_cluster_node(&network, &shared_kv, &root, "primary", primary_node.clone());
    let writer =
        sifs_posix_cluster_node(&network, &shared_kv, &root, "writer", writer_node.clone());
    let observer = sifs_posix_cluster_node(
        &network,
        &shared_kv,
        &root,
        "outsider",
        observer_node.clone(),
    );

    primary
        .bootstrap_distributed_sifs()
        .expect("primary SIFS bootstrap");

    let mut cluster = SifsPosixCluster {
        root,
        primary_node,
        writer_node,
        observer_node,
        primary,
        writer,
        observer,
        rejections: Vec::new(),
    };
    // Only the configured replica is fed by journal publication; the outsider
    // intentionally stays empty until it pulls.
    sifs_cluster_publish_metadata_until(&mut cluster, "replica catch-up", |cluster| {
        cluster.writer.posix_stat(SIFS_USERS_PATH).is_ok()
    });
    assert!(
        cluster.rejections.is_empty(),
        "replica catch-up must not reject journal batches: {:?}",
        cluster.rejections
    );
    assert!(
        cluster.observer.posix_stat(SIFS_USERS_PATH).is_err(),
        "outsider must not have been fed by the replica stream"
    );
    cluster
}

#[test]
fn sifs_non_replica_requester_routes_namespace_op_with_read_your_write() {
    let cluster = sifs_outsider_cluster("sifs-outsider-routed-namespace");
    let SifsPosixCluster {
        root,
        primary,
        mut observer,
        ..
    } = cluster;

    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        let mut primary = primary;
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    // The outsider is not in the shard's replica set; the routed mkdir's
    // response batches must still replay into its local mirror.
    observer
        .posix_mkdir_all("/users/outsider/nested")
        .expect("routed mkdir from non-replica requester");

    // Read-your-write without any further pumping: the mirror was updated by
    // the response replay alone.
    assert_eq!(
        observer
            .posix_stat("/users/outsider/nested")
            .expect("outsider reads its own routed namespace write")
            .kind,
        DfsObjectKind::Directory
    );

    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_non_replica_routed_create_is_listed_after_blocking_write() {
    let cluster = sifs_outsider_cluster("sifs-outsider-create-list-ryw");
    let SifsPosixCluster {
        root,
        primary,
        observer_node,
        mut observer,
        ..
    } = cluster;

    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        let mut primary = primary;
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    let dir = "/users/outsider-list";
    let path = "/users/outsider-list/tiny.txt";
    let bytes = b"tiny routed outsider create".to_vec();

    observer
        .posix_mkdir_all(dir)
        .expect("routed mkdir from non-replica requester");
    let mut options = DfsWriteOptions::replicated_eventual(vec![observer_node.clone()]);
    options.foreground_replica_repair = false;
    observer
        .posix_write_file(path, &bytes, options)
        .expect("committed routed create from non-replica requester");

    assert_eq!(
        observer
            .posix_read_file(path)
            .expect("outsider reads its own routed create"),
        bytes
    );
    let entries = observer
        .posix_list_dir_distributed(dir)
        .expect("outsider lists directory after routed create");
    assert!(
        entries.iter().any(|entry| entry.path == path),
        "committed routed create must be visible to an immediate distributed list: {entries:?}"
    );

    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_non_replica_node_reads_converge_via_sync_pulls() {
    let cluster = sifs_outsider_cluster("sifs-outsider-sync-pull-reads");
    let SifsPosixCluster {
        root,
        primary_node,
        primary,
        mut observer,
        ..
    } = cluster;

    let path = "/users/sync-pull.txt";
    let bytes = b"pulled through SyncPath".to_vec();
    let mut primary = primary;
    primary
        .posix_write_file(
            path,
            &bytes,
            DfsWriteOptions::replicated_eventual(vec![primary_node.clone()]),
        )
        .expect("primary local write");

    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        let mut primary = primary;
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    // The outsider never received a journal push; the distributed stat must
    // pull the shard journal from the primary and surface the file.
    let stat = observer
        .posix_stat_distributed(path)
        .expect("outsider stat converges via sync pull");
    assert_eq!(stat.size_bytes, Some(bytes.len() as u64));

    // Content reads fetch remotely as before.
    assert_eq!(
        observer
            .posix_read_file_distributed(path)
            .expect("outsider distributed read"),
        bytes
    );

    // A genuinely missing path stays NotFound: the pull catches the mirror up
    // and then reports the authoritative miss instead of spinning.
    assert!(matches!(
        observer.posix_stat_distributed("/users/never-created.txt"),
        Err(DfsPosixError::NotFound { .. })
    ));

    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_non_replica_prefix_read_reuses_authoritative_metadata_for_remote_range() {
    let cluster = sifs_outsider_cluster("sifs-outsider-prefix-range-read");
    let SifsPosixCluster {
        root,
        primary_node,
        primary,
        mut observer,
        ..
    } = cluster;

    let path = "/users/prefix-range.txt";
    let empty_path = "/users/empty-prefix-range.txt";
    let corrupt_path = "/users/corrupt-prefix-range.txt";
    let bytes = (0..(2 * 1024 * 1024 + 8192))
        .map(|index| (index % 251) as u8)
        .collect::<Vec<_>>();
    let corrupt_source_bytes = (0..(2 * 1024 * 1024 + 4096))
        .map(|index| ((index * 7) % 251) as u8)
        .collect::<Vec<_>>();
    let mut primary = primary;
    primary
        .posix_write_file(
            path,
            &bytes,
            DfsWriteOptions::replicated_eventual(vec![primary_node.clone()]),
        )
        .expect("primary local write");
    primary
        .posix_write_file(
            empty_path,
            &[],
            DfsWriteOptions::replicated_eventual(vec![primary_node.clone()]),
        )
        .expect("primary empty-file write");
    let corrupt_stat = primary
        .posix_write_file(
            corrupt_path,
            &corrupt_source_bytes,
            DfsWriteOptions::replicated_eventual(vec![primary_node]),
        )
        .expect("primary soon-corrupt file write");
    let corrupt_hash = corrupt_stat.content_hash.expect("corrupt-file hash");
    let corrupt_hex = corrupt_hash
        .strip_prefix("blake3:")
        .expect("blake3 corrupt-file hash");
    let corrupt_blob_path = root
        .join("primary")
        .join("content")
        .join("blobs")
        .join(&corrupt_hex[..2])
        .join(corrupt_hex);
    let mut corrupted_bytes = corrupt_source_bytes.clone();
    corrupted_bytes[0] ^= 0xff;
    std::fs::write(&corrupt_blob_path, corrupted_bytes)
        .expect("corrupt primary blob without changing its size");

    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    let prefix = observer
        .posix_read_file_prefix_distributed(path, 23)
        .expect("outsider authoritative prefix read");
    assert_eq!(prefix.bytes, bytes[..23]);
    assert!(prefix.truncated);
    assert!(
        observer.posix_read_file(path).is_err(),
        "an uncached prefix read must not materialize the full remote object locally"
    );

    let opened = observer
        .posix_stat_distributed(path)
        .expect("outsider authoritative open metadata");
    let opened_range = observer
        .posix_read_file_range_for_opened_object(path, &opened.object_id, 17, 31, true)
        .expect("outsider opened-object remote range read");
    assert_eq!(opened_range, bytes[17..48]);
    assert!(
        observer.posix_read_file(path).is_err(),
        "an opened-object range read must not materialize the full remote object locally"
    );

    let complete = observer
        .posix_read_file_prefix_distributed(path, bytes.len())
        .expect("outsider exact-size complete range read");
    assert_eq!(complete.bytes, bytes);
    assert!(!complete.truncated);

    let empty = observer
        .posix_read_file_prefix_distributed(empty_path, 0)
        .expect("outsider zero-length prefix read");
    assert!(empty.bytes.is_empty());
    assert!(!empty.truncated);

    let corrupt_error = observer
        .posix_read_file_prefix_distributed(corrupt_path, corrupt_source_bytes.len())
        .expect_err("complete chunked range must verify the committed whole-object hash");
    assert!(matches!(
        corrupt_error,
        DfsPosixError::Dfs(DfsError::ContentHashMismatch { expected, .. })
            if expected == corrupt_hash
    ));

    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_replica_distributed_stat_prefers_primary_tombstone_over_stale_local_hit() {
    let mut cluster = sifs_posix_cluster("sifs-replica-stat-primary-tombstone");
    let path = "/users/stat-stale-live.txt";
    let bytes = b"writer-local stale entry should lose to primary tombstone".to_vec();

    sifs_cluster_routed_posix_write(&mut cluster, path, &bytes);
    assert_eq!(
        cluster.writer.posix_read_file(path).expect("writer read"),
        bytes
    );
    assert!(cluster.writer.posix_stat(path).is_ok());

    cluster.primary.posix_unlink(path).expect("primary unlink");
    assert!(matches!(
        cluster.primary.posix_stat(path),
        Err(DfsPosixError::NotFound { .. })
    ));
    assert!(
        cluster.writer.posix_stat(path).is_ok(),
        "test setup must leave a stale local live entry on the writer"
    );

    let SifsPosixCluster {
        root,
        mut primary,
        mut writer,
        ..
    } = cluster;
    let stop_primary = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop_primary);
    let primary_thread = std::thread::spawn(move || {
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });

    let distributed_stat = writer.posix_stat_distributed(path);
    stop_primary.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    assert!(
        matches!(distributed_stat, Err(DfsPosixError::NotFound { .. })),
        "distributed stat must prefer the shard primary tombstone over a stale replica-local hit, got {distributed_stat:?}"
    );

    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_replica_distributed_read_prefers_primary_over_stale_local_hit() {
    let mut cluster = sifs_posix_cluster("sifs-replica-read-primary-current");
    let path = "/users/read-stale-live.txt";
    let old = b"writer-local stale payload should lose to primary current payload".to_vec();
    let new = b"primary current payload must win the distributed read".to_vec();

    sifs_cluster_routed_posix_write(&mut cluster, path, &old);
    assert_eq!(
        cluster
            .writer
            .posix_read_file(path)
            .expect("writer old read"),
        old
    );

    cluster
        .primary
        .posix_write_file(
            path,
            &new,
            sifs_cluster_write_options(&cluster.primary_node.clone()),
        )
        .expect("primary overwrite");
    assert_eq!(
        cluster
            .primary
            .posix_read_file(path)
            .expect("primary new read"),
        new
    );
    assert_eq!(
        cluster
            .writer
            .posix_read_file(path)
            .expect("writer stale read"),
        old,
        "test setup must leave a stale local live entry on the writer"
    );

    let read = {
        let primary = &mut cluster.primary;
        let writer = &mut cluster.writer;
        sifs_cluster_blocking_distributed_read_with_pump(
            writer,
            path,
            "replica current read prefers primary object",
            || {
                primary.process_incoming().expect("primary pump");
            },
        )
    };
    assert_eq!(
        read, new,
        "distributed/current reads must prefer the shard primary over a stale replica-local hit"
    );

    std::fs::remove_dir_all(&cluster.root).ok();
}

