#[test]
fn sifs_replica_primary_lookup_read_retries_after_stale_location_without_local_metadata() {
    let cluster = sifs_posix_cluster("sifs-replica-read-stale-source-no-local-metadata");
    let SifsPosixCluster {
        root,
        primary_node,
        writer_node,
        mut primary,
        mut writer,
        mut observer,
        ..
    } = cluster;
    let path = "/users/replica-read-stale-source.txt";
    let bytes = b"replica primary lookup should retry a stale advertised location".to_vec();
    let stat = primary
        .posix_write_file(
            path,
            &bytes,
            DfsWriteOptions::replicated_eventual(vec![primary_node.clone()]),
        )
        .expect("primary local write");

    let mut object = primary
        .metadata()
        .object(&stat.object_id)
        .expect("primary object")
        .clone();
    object.current_locations = vec![writer_node.clone(), primary_node.clone()];
    // Seed the current primary's authoritative test state without scheduling a
    // journal publication to the observer. The behavior under test starts
    // with no local file metadata and exercises only routed lookup plus exact
    // content retry; queued replica catch-up is covered separately.
    primary
        .metadata_backend
        .as_mut()
        .expect("primary metadata backend")
        .put_object(&object)
        .expect("primary backend stale location");
    primary
        .apply_metadata_object_to_service_state(object)
        .expect("primary in-memory stale location");

    assert!(
        matches!(
            observer.posix_stat(path),
            Err(DfsPosixError::NotFound { .. })
        ),
        "observer should not have local metadata before the distributed read"
    );

    let stop = Arc::new(AtomicBool::new(false));
    let primary_stop = Arc::clone(&stop);
    let primary_thread = std::thread::spawn(move || {
        while !primary_stop.load(Ordering::SeqCst) {
            primary.process_incoming().expect("primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        primary
    });
    let writer_stop = Arc::clone(&stop);
    let writer_thread = std::thread::spawn(move || {
        while !writer_stop.load(Ordering::SeqCst) {
            writer.process_incoming().expect("writer stale-source pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        writer
    });

    let started = Instant::now();
    assert_eq!(
        observer
            .posix_read_file_distributed(path)
            .expect("observer retries from stale source to primary"),
        bytes
    );
    assert!(
        started.elapsed() < Duration::from_secs(1),
        "stale-source retry should not spend the full remote-read budget"
    );
    assert!(
        matches!(
            observer.posix_stat(path),
            Err(DfsPosixError::NotFound { .. })
        ),
        "read-only primary lookup must not install metadata on the replica"
    );

    stop.store(true, Ordering::SeqCst);
    primary_thread.join().expect("primary thread");
    writer_thread.join().expect("writer thread");

    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_routed_namespace_op_follows_authority_redirect() {
    let root = temp_root("sifs-authority-redirect");
    let primary_node =
        NodeId::from_legacy_named("node_sifs_redirect_old_primary").expect("old primary");
    let writer_node =
        NodeId::from_legacy_named("node_sifs_redirect_new_primary").expect("new primary");
    let observer_node =
        NodeId::from_legacy_named("node_sifs_redirect_requester").expect("requester");

    let network = InProcessNetwork::new();
    let shard_config = |primary: &NodeId, epoch: u64| DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "root".to_string(),
        primary_node_id: primary.clone(),
        replica_node_ids: vec![primary_node.clone(), writer_node.clone()],
        epoch,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };

    // Current control-plane view: the shard moved to `writer_node` at epoch 2.
    let kv_current = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    kv_current.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                writer_node.clone(),
            )))
            .expect("current filesystem config");
        control
            .put_metadata_shard(&shard_config(&writer_node, 2))
            .expect("current shard config");
    });
    // The requester's stale view still names the old primary at epoch 1.
    let kv_stale = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    kv_stale.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                writer_node.clone(),
            )))
            .expect("stale filesystem config");
        control
            .put_metadata_shard(&shard_config(&primary_node, 1))
            .expect("stale shard config");
    });
    let stale_requester_snapshot = kv_stale
        .with_client(|kv| kv.try_snapshot())
        .expect("stale requester control-plane snapshot");
    kv_stale.with_client(|kv| {
        DfsControlPlaneStore::new(kv)
            .put_metadata_shard(&shard_config(&writer_node, 2))
            .expect("refreshed requester shard config")
    });

    let old_primary =
        sifs_posix_cluster_node(&network, &kv_current, &root, "old-primary", primary_node);
    let mut new_primary =
        sifs_posix_cluster_node(&network, &kv_current, &root, "new-primary", writer_node);
    let mut requester =
        sifs_posix_cluster_node(&network, &kv_stale, &root, "requester", observer_node);
    requester =
        requester.with_boxed_control_plane(Box::new(RefreshingDfsControlPlaneKvClient::new(
            InProcessKvStore::restore(stale_requester_snapshot)
                .expect("restore stale requester control plane"),
            kv_stale.clone(),
            Arc::new(AtomicUsize::new(0)),
        )));
    new_primary
        .bootstrap_distributed_sifs()
        .expect("new primary SIFS bootstrap");

    let stop = Arc::new(AtomicBool::new(false));
    let old_stop = Arc::clone(&stop);
    let old_thread = std::thread::spawn(move || {
        let mut node = old_primary;
        while !old_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("old primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });
    let new_stop = Arc::clone(&stop);
    let new_thread = std::thread::spawn(move || {
        let mut node = new_primary;
        while !new_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("new primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });

    // The requester routes on its stale view to the old primary, which
    // rejects with the current authority; the operation must follow the
    // redirect and succeed at the new primary.
    requester
        .posix_mkdir_all("/users/redirected")
        .expect("routed mkdir follows authority redirect");
    assert_eq!(
        requester
            .posix_stat("/users/redirected")
            .expect("requester reads its own redirected write")
            .kind,
        DfsObjectKind::Directory
    );

    stop.store(true, Ordering::SeqCst);
    old_thread.join().expect("old primary thread");
    new_thread.join().expect("new primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_routed_write_follows_authority_redirect() {
    let root = temp_root("sifs-write-authority-redirect");
    let primary_node =
        NodeId::from_legacy_named("node_sifs_write_redirect_old_primary").expect("old primary");
    let writer_node =
        NodeId::from_legacy_named("node_sifs_write_redirect_new_primary").expect("new primary");
    let requester_node =
        NodeId::from_legacy_named("node_sifs_write_redirect_requester").expect("requester");

    let network = InProcessNetwork::new();
    let shard_config = |primary: &NodeId, epoch: u64| DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "root".to_string(),
        primary_node_id: primary.clone(),
        replica_node_ids: vec![primary_node.clone(), writer_node.clone()],
        epoch,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };

    let kv_current = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    kv_current.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                writer_node.clone(),
            )))
            .expect("current filesystem config");
        control
            .put_metadata_shard(&shard_config(&writer_node, 2))
            .expect("current shard config");
    });
    let kv_stale = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    kv_stale.with_client(|kv| {
        let mut control = DfsControlPlaneStore::new(kv);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                writer_node.clone(),
            )))
            .expect("stale filesystem config");
        control
            .put_metadata_shard(&shard_config(&primary_node, 1))
            .expect("stale shard config");
    });
    let stale_requester_snapshot = kv_stale
        .with_client(|kv| kv.try_snapshot())
        .expect("stale requester control-plane snapshot");
    kv_stale.with_client(|kv| {
        DfsControlPlaneStore::new(kv)
            .put_metadata_shard(&shard_config(&writer_node, 2))
            .expect("refreshed requester shard config")
    });

    let old_primary =
        sifs_posix_cluster_node(&network, &kv_current, &root, "old-primary", primary_node);
    let mut new_primary = sifs_posix_cluster_node(
        &network,
        &kv_current,
        &root,
        "new-primary",
        writer_node.clone(),
    );
    let mut requester = sifs_posix_cluster_node(
        &network,
        &kv_stale,
        &root,
        "requester",
        requester_node.clone(),
    );
    requester =
        requester.with_boxed_control_plane(Box::new(RefreshingDfsControlPlaneKvClient::new(
            InProcessKvStore::restore(stale_requester_snapshot)
                .expect("restore stale requester control plane"),
            kv_stale.clone(),
            Arc::new(AtomicUsize::new(0)),
        )));
    new_primary
        .bootstrap_distributed_sifs()
        .expect("new primary SIFS bootstrap");

    let stop = Arc::new(AtomicBool::new(false));
    let old_stop = Arc::clone(&stop);
    let old_thread = std::thread::spawn(move || {
        let mut node = old_primary;
        while !old_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("old primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });
    let new_stop = Arc::clone(&stop);
    let new_thread = std::thread::spawn(move || {
        let mut node = new_primary;
        while !new_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("new primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });

    requester
        .posix_mkdir_all("/users")
        .expect("parent mkdir follows authority redirect");
    let path = "/users/write-redirected.txt";
    let bytes = b"routed write follows current primary".to_vec();
    let stat = requester
        .posix_write_file(
            path,
            &bytes,
            DfsWriteOptions::replicated_eventual(vec![requester_node, writer_node]),
        )
        .expect("routed write follows authority redirect");
    assert_eq!(stat.size_bytes, Some(bytes.len() as u64));
    assert_eq!(
        requester
            .posix_read_file_distributed(path)
            .expect("requester reads redirected write"),
        bytes
    );

    stop.store(true, Ordering::SeqCst);
    old_thread.join().expect("old primary thread");
    new_thread.join().expect("new primary thread");
    std::fs::remove_dir_all(&root).ok();
}

#[test]
fn sifs_routed_write_refreshes_stale_receiver_control_plane() {
    let root = temp_root("sifs-write-refresh-stale-receiver");
    let old_primary_node =
        NodeId::from_legacy_named("node_sifs_write_refresh_old_primary").expect("old primary");
    let current_primary_node = NodeId::from_legacy_named("node_sifs_write_refresh_current_primary")
        .expect("current primary");
    let requester_node =
        NodeId::from_legacy_named("node_sifs_write_refresh_requester").expect("requester");

    let network = InProcessNetwork::new();
    let shard_config = |primary: &NodeId, epoch: u64| DfsMetadataShardConfig {
        file_system_id: sifs_file_system_id(),
        shard_id: "root".to_string(),
        primary_node_id: primary.clone(),
        replica_node_ids: vec![old_primary_node.clone(), current_primary_node.clone()],
        epoch,
        assignment: DfsMetadataShardAssignment::Root,
        default_policy: DfsObjectPolicy::ReplicatedEventual,
    };
    let put_control_plane = |kv_client: &SharedDfsControlPlaneKvClient<InProcessKvStore>,
                             primary: &NodeId,
                             epoch: u64| {
        kv_client.with_client(|kv| {
            let mut control = DfsControlPlaneStore::new(kv);
            control
                .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                    current_primary_node.clone(),
                )))
                .expect("filesystem config");
            control
                .put_metadata_shard(&shard_config(primary, epoch))
                .expect("shard config");
        });
    };

    let kv_current = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    put_control_plane(&kv_current, &current_primary_node, 2);
    let kv_old_primary = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    put_control_plane(&kv_old_primary, &current_primary_node, 2);
    let kv_requester = SharedDfsControlPlaneKvClient::new(InProcessKvStore::new());
    put_control_plane(&kv_requester, &old_primary_node, 1);
    let stale_requester_snapshot = kv_requester
        .with_client(|kv| kv.try_snapshot())
        .expect("stale requester control-plane snapshot");
    put_control_plane(&kv_requester, &current_primary_node, 2);

    let refreshes = Arc::new(AtomicUsize::new(0));

    let mut old_primary = sifs_posix_cluster_node(
        &network,
        &kv_old_primary,
        &root,
        "old-primary",
        old_primary_node.clone(),
    );
    let mut current_primary = sifs_posix_cluster_node(
        &network,
        &kv_old_primary,
        &root,
        "current-primary",
        current_primary_node.clone(),
    );
    let mut requester = sifs_posix_cluster_node(
        &network,
        &kv_requester,
        &root,
        "requester",
        requester_node.clone(),
    );
    requester =
        requester.with_boxed_control_plane(Box::new(RefreshingDfsControlPlaneKvClient::new(
            InProcessKvStore::restore(stale_requester_snapshot)
                .expect("restore stale requester control plane"),
            kv_requester.clone(),
            Arc::new(AtomicUsize::new(0)),
        )));
    current_primary
        .bootstrap_distributed_sifs()
        .expect("current primary SIFS bootstrap");

    let parent_stop = Arc::new(AtomicBool::new(false));
    let old_parent_stop = Arc::clone(&parent_stop);
    let old_parent_thread = std::thread::spawn(move || {
        let mut node = old_primary;
        while !old_parent_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("old primary parent pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        node
    });
    let current_parent_stop = Arc::clone(&parent_stop);
    let current_parent_thread = std::thread::spawn(move || {
        let mut node = current_primary;
        while !current_parent_stop.load(Ordering::SeqCst) {
            node.process_incoming()
                .expect("current primary parent pump");
            std::thread::sleep(Duration::from_millis(1));
        }
        node
    });
    requester
        .posix_mkdir_all("/users")
        .expect("requester creates parent through current primary");
    parent_stop.store(true, Ordering::SeqCst);
    old_primary = old_parent_thread.join().expect("old primary parent thread");
    current_primary = current_parent_thread
        .join()
        .expect("current primary parent thread");

    let mut stale_current_store = InProcessKvStore::new();
    {
        let mut control = DfsControlPlaneStore::new(&mut stale_current_store);
        control
            .put_file_system_config(&DfsFileSystemConfig::from(&distributed_sifs(
                current_primary_node.clone(),
            )))
            .expect("stale receiver filesystem config");
        control
            .put_metadata_shard(&shard_config(&old_primary_node, 1))
            .expect("stale receiver shard config");
    }
    let refreshing_current_control = RefreshingDfsControlPlaneKvClient::new(
        stale_current_store,
        kv_current,
        Arc::clone(&refreshes),
    );
    current_primary =
        current_primary.with_boxed_control_plane(Box::new(refreshing_current_control));

    let stop = Arc::new(AtomicBool::new(false));
    let old_stop = Arc::clone(&stop);
    let old_thread = std::thread::spawn(move || {
        let mut node = old_primary;
        while !old_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("old primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });
    let current_stop = Arc::clone(&stop);
    let current_thread = std::thread::spawn(move || {
        let mut node = current_primary;
        while !current_stop.load(Ordering::SeqCst) {
            node.process_incoming().expect("current primary pump");
            std::thread::sleep(Duration::from_millis(1));
        }
    });

    let path = "/users/write-refreshes-stale-receiver.txt";
    let bytes = b"stale receiver refreshes control plane".to_vec();
    requester
        .posix_write_file(
            path,
            &bytes,
            DfsWriteOptions::replicated_eventual(vec![requester_node, current_primary_node]),
        )
        .expect("routed write refreshes stale receiver control plane");
    assert!(
        refreshes.load(Ordering::SeqCst) > 0,
        "current primary should refresh its stale control-plane view"
    );

    stop.store(true, Ordering::SeqCst);
    old_thread.join().expect("old primary thread");
    current_thread.join().expect("current primary thread");
    std::fs::remove_dir_all(&root).ok();
}

